static bool stAlignedChainBindingsMatch(const SStreamTriggerTask *task, const SAlignedChainUpdate *update) {
  const SArray *const *tables = tSimpleHashGet(task->pVirtTableGidIndex, &update->gid, sizeof(update->gid));
  if (!tables || taosArrayGetSize(*tables) != taosArrayGetSize(update->tables)) return false;
  for (int32_t i = 0; i < taosArrayGetSize(update->tables); ++i) {
    const SSTriggerVirtTableInfo *frozen = taosArrayGetP(update->tables, i);
    const SSTriggerVirtTableInfo *live = tSimpleHashGet(task->pVirtTableInfos, &frozen->tbUid, sizeof(frozen->tbUid));
    if (!live || !stTriggerTaskMatchVirtTableInfo(live, update->gid) || !live->colRefsInitialized ||
        frozen->tbVer != live->tbVer || taosArrayGetSize(frozen->pTrigColRefs) != taosArrayGetSize(live->pTrigColRefs))
      return false;
    for (int32_t j = 0; j < taosArrayGetSize(frozen->pTrigColRefs); ++j) {
      const SSTriggerTableColRef *a = taosArrayGet(frozen->pTrigColRefs, j);
      const SSTriggerTableColRef *b = taosArrayGet(live->pTrigColRefs, j);
      if (a->otbUid != b->otbUid || a->otbSuid != b->otbSuid || a->otbVgId != b->otbVgId ||
          taosArrayGetSize(a->pColMatches) != taosArrayGetSize(b->pColMatches))
        return false;
      for (int32_t k = 0; k < taosArrayGetSize(a->pColMatches); ++k) {
        const SSTriggerColMatch *x = taosArrayGet(a->pColMatches, k);
        const SSTriggerColMatch *y = taosArrayGet(b->pColMatches, k);
        if (x->otbColId != y->otbColId || x->vtbSlotId != y->vtbSlotId) return false;
      }
    }
  }
  return true;
}

static int32_t stRetireAlignedFollower(SSTriggerRealtimeGroup *group, uint64_t repairId, bool restore);

static int32_t stRetireCancelledAlignedFollowers(SSTriggerRealtimeContext *ctx) {
  for (SSTriggerRealtimeGroup *group = TD_DLIST_HEAD(&ctx->groupsWithAlignedWork), *next; group; group = next) {
    next = TD_DLIST_NODE_NEXT_WITH_FIELD(group, alignedWorkNode);
    taosRLockLatch(&ctx->pTask->prevWindowUpdateLock);
    const SAlignedChainUpdate *update = ctx->pTask->pAlignedChainUpdate;
    bool                       retired = !update || update->id != group->alignedCatchupId;
    taosRUnLockLatch(&ctx->pTask->prevWindowUpdateLock);
    if (retired) TAOS_CHECK_RETURN(stRetireAlignedFollower(group, group->alignedCatchupId, true));
  }
  return 0;
}

static bool stAlignedPageHasFrozenInput(const SSTriggerRealtimeGroup *group, const SAlignedChainUpdate *update) {
  int32_t   pos = 0;
  SObjList *records = NULL;
  while ((records = tSimpleHashIterate(group->pWalMetas, records, &pos))) {
    const SSTriggerReaderDataKey *key = tSimpleHashGetKey(records, NULL);
    if (key->readerKind != STRIGGER_READER_KIND_INTERNAL) continue;
    const SSTriggerOrigTableInfo *table =
        tSimpleHashGet(group->pContext->pTask->pOrigTableInfos, &key->logicalUid, sizeof(key->logicalUid));
    if (!table) continue;
    const SAlignedChainReader *bound = stAlignedReaderForVg(update, table->vgId);
    if (!bound) continue;
    SObjListIter cursor = {0};
    taosObjListInitIter(records, &cursor, TOBJLIST_ITER_FORWARD);
    const SSTriggerMetaData *meta;
    while ((meta = taosObjListIterNext(&cursor)))
      if (meta->ver <= bound->version && meta->ekey > group->oldThreshold) return true;
  }
  return false;
}

static int32_t stRetireAlignedFollower(SSTriggerRealtimeGroup *group, uint64_t repairId, bool restore) {
  if (restore && group->alignedOrdinaryChain) TSWAP(group->pWindowChain, group->alignedOrdinaryChain);
  stWindowChainDestroy(&group->alignedOrdinaryChain);
  if (group->alignedRepairId == repairId) group->alignedRepairId = 0;
  group->alignedCatchupId = 0;
  group->alignedDraining = false;
  stUpdateAlignedWorkGroup(group);
  return stRealtimeGroupUpdateExecTime(group, taosGetTimestampNs(), true);
}

static int32_t stAcceptAlignedChain(SSTriggerRealtimeContext *ctx) {
  SStreamTriggerTask *pTask = ctx->pTask;
  taosWLockLatch(&pTask->prevWindowUpdateLock);
  SAlignedChainUpdate *update = pTask->pAlignedChainUpdate;
  int32_t                  code = 0;
  SSTriggerRealtimeGroup **target = NULL;
  if (update && !update->checked) {
    target = tSimpleHashGet(ctx->pGroups, &update->gid, sizeof(update->gid));
    if (update->future) {
      if (target && (*target)->alignedFuture == update->future) {
        SAlignedFutureRepair *future = (*target)->alignedFuture;
        future->running = false;
        future->after = update->frontier;
        if (!update->outstanding) {
          stReleaseAlignedFuture(&(*target)->alignedFuture, true);
          stClearAlignedRepairBinding(*target);
        } else {
          code = stScheduleAlignedFuture(*target, (*target)->oldThreshold);
        }
      }
      update->checked = !code;
      goto end;
    }
    bool match = target && ((*target)->alignedRepairId == update->id || (*target)->alignedCatchupId == update->id) &&
                 (update->following || update->catchup || (*target)->oldThreshold == update->frontier) &&
                 (update->catchup || update->normal || !(*target)->nestedInputRegistered) && !ctx->timeAlignRestart &&
                 !ctx->suppressOutput && !stTriggerTaskHasNestedRecoveryOwner(pTask) &&
                 !IS_PATCHING_VITRUAL_TABLE(ctx) && stAlignedChainBindingsMatch(pTask, update);
    bool drained = match && !(*target)->nestedInputRegistered && (*target)->newThreshold == (*target)->oldThreshold &&
                   TD_DLIST_NODE_NEXT(*target) == NULL && TD_DLIST_TAIL(&ctx->groupsToCheck) != *target;
    bool unread = false;
    for (int32_t i = 0; match && i < taosArrayGetSize(update->readers); ++i) {
      SAlignedChainReader  *bound = taosArrayGet(update->readers, i);
      SSTriggerWalProgress *reader = tSimpleHashGet(ctx->pReaderWalProgress, &bound->vgId, sizeof(bound->vgId));
      match = reader && reader->pTaskAddr->taskId == bound->taskId && bound->sourceId &&
              reader->previousSourceId == bound->sourceId;
      int64_t  cursor = reader ? reader->lastScanVer : 0;
      uint64_t round = reader ? reader->timeAlignRound : 0;
      if (match && !update->hasInputCut) {
        bound->liveCursor = cursor;
        bound->liveRound = round;
        bound->proofCursor = TMIN(bound->liveCursor, bound->version + 1);
      }
      if (match && cursor <= bound->version) {
        drained = false;
        unread = true;
      }
      if (match && !update->following && !update->catchup && update->hasInputCut && update->heldNormalPage) {
        match = cursor == bound->liveCursor && round == bound->liveRound;
      }
    }
    if (match && update->tailPending) {
      SSTriggerRealtimeGroup *group = *target;
      if (update->tailDone) {
        if (update->outstanding) {
          code = stOwnAlignedRepairBinding(group);
          if (code) goto end;
          SAlignedFutureRepair *future = taosMemoryCalloc(1, sizeof(*future));
          if (!future) {
            code = terrno;
            goto end;
          }
          future->refs = 1;
          future->anchor = group->alignedInputFloor;
          future->carry = update->carry;
          future->after = update->caughtFrontier;
          future->target = future->after;
          if (group->alignedFuture) {
            future->target = TMAX(future->target, group->alignedFuture->target);
            future->anchor = TMIN(future->anchor, group->alignedFuture->anchor);
            future->after = TMIN(future->after, group->alignedFuture->after);
            stReleaseAlignedFuture(&group->alignedFuture, true);
          }
          group->alignedFuture = future;
          code = stScheduleAlignedFuture(group, group->oldThreshold);
          if (code) goto end;
        }
        code = stRetireAlignedFollower(group, update->id, false);
        update->checked = !code;
      } else if (drained && !listNEles(&group->pendingNestedEvents) && !listNEles(&group->pendingNestedParWinEvents) &&
                 !stRealtimeCalcGroupIsRunning(pTask, ctx->sessionId, group->gid)) {
        update->caughtUp = true;
        update->caughtFrontier = group->oldThreshold;
      }
      goto end;
    }
    if (match && update->betweenPages) {
      SSTriggerRealtimeGroup *group = *target;
      if (group->alignedNormalPage || group->nestedInputRegistered || stRealtimeContextHasPendingWalPulls(ctx))
        goto end;
      bool next = group->newThreshold > group->oldThreshold;
      if (!unread && (!next || !stAlignedPageHasFrozenInput(group, update))) {
        code = stRetireAlignedFollower(group, update->id, false);
        update->checked = !code;
        goto end;
      }
      if (!next) goto end;
      stReleaseAlignedNormalPage(&update->normal);
      update->frontier = group->oldThreshold;
      update->ordinaryFrontier = group->newThreshold;
      update->ordinal = update->matchedPrefix = 0;
      update->mismatch = false;
      update->comparing = update->proofComplete = update->prepared = update->committed = false;
      update->betweenPages = false;
    }
    if (match && !update->hasInputCut) {
      update->heldNormalPage = (*target)->newThreshold > (*target)->oldThreshold;
      update->ordinaryFrontier = (*target)->newThreshold;
    }
    update->hasInputCut = match;
    if (match && update->compare && !update->normal) {
      SAlignedNormalPage *page = taosMemoryCalloc(1, sizeof(*page));
      if (!page) {
        code = terrno;
        goto end;
      }
      page->peers = taosArrayInit(4, sizeof(SWindowChainPeerGroup));
      if (!page->peers) {
        taosMemoryFree(page);
        code = terrno;
        goto end;
      }
      page->refs = 2;
      update->normal = page;
      (*target)->alignedNormalPage = page;
    }
    if (match && update->catchup) {
      (*target)->alignedCatchupId = update->id;
      (*target)->alignedDraining = !drained;
      if (drained) {
        update->caughtFrontier = (*target)->oldThreshold;
        update->caughtUp = true;
        update->superseded = (*target)->alignedRepairId && (*target)->alignedRepairId != update->id;
      }
    }
    if (match && update->committed) {
      SSTriggerRealtimeGroup *group = *target;
      int64_t                 now = taosGetTimestampNs();
      bool                    follow = update->normal && !update->mismatch && unread;
      if (update->mismatch && update->matchedPrefix) {
        SAlignedNormalPage *page = update->normal;
        if (page->replayIndex < update->matchedPrefix) {
          if (!update->following) {
            stWindowChainRearmDelayClocks(update->chain, now);
            TSWAP(group->pWindowChain, update->chain);
            TSWAP(group->alignedOrdinaryChain, update->chain);
            update->following = true;
          }
          group->alignedCatchupId = update->id;
          group->alignedDraining = true;
          page->prefixEnd = update->matchedPrefix;
          goto end;
        }
        // Both source versions admitted this portion. Its actual ordinary effects were already
        // submitted on the corrected chain, so the history continuation starts after that peer.
        const SWindowChainPeerGroup *last = taosArrayGet(page->peers, update->matchedPrefix - 1);
        update->frontier = last->ts;
      }
      if (update->mismatch &&
          stWindowChainCaptureRepairCarry(update->following ? group->pWindowChain : update->chain,
                                          update->following ? group->alignedOrdinaryChain : group->pWindowChain,
                                          update->repairFrontier, &update->carry)) {
        // P1 can have already closed this correction's last affected leaf. Keep only a still-open
        // prefix. The ordinary branch must consume the conflicting page using its own input.
        if (update->following) {
          TSWAP(group->pWindowChain, update->chain);
          TSWAP(group->pWindowChain, group->alignedOrdinaryChain);
        }
        group->alignedCatchupId = update->id;
        group->alignedDraining = true;
        atomic_store_8(&update->normal->released, 1);
        update->tailPending = update->catchup = true;
        update->following = update->comparing = update->compare = update->committed = false;
        goto end;
      }
      if (!update->following && !update->mismatch) {
        stWindowChainRearmDelayClocks(update->chain, now);
        TSWAP(group->pWindowChain, update->chain);
        if (follow) TSWAP(group->alignedOrdinaryChain, update->chain);
      }
      if (update->normal) atomic_store_8(&update->normal->released, 1);
      if (follow) {
        group->alignedCatchupId = update->id;
        group->alignedDraining = true;
        update->following = update->betweenPages = true;
      } else {
        code = stRetireAlignedFollower(group, update->id, update->mismatch);
        if (code) goto end;
      }
      if (!update->mismatch) {
        group->recalcNextWindow = false;
        group->timeAlignNestedRepair = (STimeWindow){.skey = INT64_MAX, .ekey = INT64_MIN};
        stClearAlignedRepairBinding(group);
      }
      if (follow) {
        code = stRealtimeGroupUpdateExecTime(group, now, true);
        goto end;
      }
    }
    ST_TASK_DLOG("nested handoff id:%" PRIu64 " frontier:%" PRId64 " match:%d", update->id, update->frontier, match);
    if (!match && target && (*target)->alignedCatchupId == update->id) {
      code = stRetireAlignedFollower(*target, update->id, true);
      if (code) goto end;
    }
    if (!match && update->normal) atomic_store_8(&update->normal->released, 1);
    update->prepared = match && update->proofComplete;
    update->checked = !match || update->committed;
  }
end:
  if (target) stUpdateAlignedWorkGroup(*target);
  taosWUnLockLatch(&pTask->prevWindowUpdateLock);
  return code;
}

// Both BOUND and the first WAL read start at IDLE. Only an empty, fully rolled-back
// poll can preserve the prior cut when the local dnode has stopped sending requests.
static int32_t stAbortIdleAlignedPoll(SSTriggerRealtimeContext *ctx, int32_t code) {
  if (!ctx->timeAlignRound) return code;
  SStreamTriggerTask *task = ctx->pTask;
  bool stopping = code == TSDB_CODE_APP_IS_STOPPING && ctx == task->pRealtimeContext && ctx->boundDetermined &&
                  BIT_FLAG_TEST_MASK(task->addOptions, STREAM_OPTION_NESTED_WINDOW_PLAN) &&
                  atomic_load_32(&task->alignedCheckpointHold) && stAlignedWalInputsDrained(ctx, false) &&
                  !stTriggerTaskRealtimeContextHasCutoverBlocker(ctx, true);
  if (stopping || ctx->status == STRIGGER_CONTEXT_DETERMINE_BOUND) {
    TAOS_CHECK_RETURN(stDropTimeAlignBoundary(ctx, false));
    if (stopping || stTimeAlignSourceRoundNeedsRetry(code)) return TSDB_CODE_SUCCESS;
  }
  return code;
}

static bool stRealtimeGroupHasPendingParams(const SSTriggerRealtimeGroup *group) {
  return group->pPendingCalcParams.neles || group->pPendingParWinCalcParams.neles;
}

static int32_t stRealtimeContextBeginWalDrain(SSTriggerRealtimeContext *ctx, int64_t now) {
  ctx->drainingWalCheckpoint = true;
  if (!ctx->calcParamPool.size) return TSDB_CODE_SUCCESS;

  // Dispatch queued WAL work before capturing the requests this checkpoint must wait for.
  int32_t                  iter = 0;
  SSTriggerRealtimeGroup **group = NULL;
  while ((group = tSimpleHashIterate(ctx->pGroups, group, &iter))) {
    if (stRealtimeGroupHasPendingParams(*group)) TAOS_CHECK_RETURN(stRealtimeGroupUpdateExecTime(*group, now, true));
  }
  return TSDB_CODE_SUCCESS;
}

static int32_t stRealtimeContextCaptureWalCheckpoint(SSTriggerRealtimeContext *ctx) {
  if (ctx->pWalCheckpointWaits || ctx->calcParamPool.size || ctx->pCalcReq || TD_DLIST_NELES(&ctx->groupsToCheck) ||
      taosArrayGetSize(ctx->groupsToDelete) || ctx->calcGroupValueMisses || ctx->notifyGroupColValuePending ||
      stRealtimeContextHasPendingWalPulls(ctx))
    return TSDB_CODE_SUCCESS;
  ctx->walCheckpointWaitIndex = 0;
  return stTriggerTaskCaptureCalcWaits(ctx->pTask, NULL, &ctx->pWalCheckpointWaits);
}

static bool stRealtimeContextWalCalcIsWaiting(SSTriggerRealtimeContext *ctx) {
  return stTriggerTaskCalcIsWaiting(ctx->pTask, ctx->pWalCheckpointWaits, &ctx->walCheckpointWaitIndex);
}

static void stRealtimeContextFinishWalCheckpoint(SSTriggerRealtimeContext *ctx, int64_t now) {
  SStreamTriggerTask *task = ctx->pTask;
  if (atomic_load_32((int32_t *)&task->task.status) == STREAM_STATUS_FAILED || stRealtimeContextWalCalcIsWaiting(ctx))
    return;

  // New timer calculations can reuse the slots while WAL stays at the captured boundary.
  int32_t               iter = 0;
  SSTriggerWalProgress *progress = NULL;
  while ((progress = tSimpleHashIterate(ctx->pReaderWalProgress, progress, &iter))) {
    progress->doneVer = progress->lastScanVer;
    progress->alignedDrainedVer = 0;
    stTriggerTaskUpdateReaderProgress(task, progress);
  }
  task->pendingPeriodicCheckpoint = true;
  stTriggerTaskGeneratePeriodicCheckpoint(task, ctx, now);
  if (!task->pendingPeriodicCheckpoint) {
    taosArrayDestroy(ctx->pWalCheckpointWaits);
    ctx->pWalCheckpointWaits = NULL;
    ctx->drainingWalCheckpoint = false;
    ctx->walStallDeadlineUs = 0;
    stCancelWalCheckpointWake(task);
    if (ctx->pMaxDelayHeap->min) {
      SSTriggerRealtimeGroup *first = container_of(ctx->pMaxDelayHeap->min, SSTriggerRealtimeGroup, heapNode);
      int64_t                 finished = taosGetTimestampNs();
      if (first->nextExecTime <= finished) ctx->walCheckpointMaxDelayCutoff = finished;
    }
  }
}

static int32_t stRealtimeContextCheckAt(SSTriggerRealtimeContext *pContext, int64_t now) {
  int32_t             code = TSDB_CODE_SUCCESS;
  int32_t             lino = 0;
  int64_t             waitingGroups = 0;
  SStreamTriggerTask *pTask = pContext->pTask;
  int64_t             checkStartMonoUs = streamTaskGetMonotonicUs();
  int64_t             checkEndMonoUs = 0;
  bool                nested = BIT_FLAG_TEST_MASK(pTask->addOptions, STREAM_OPTION_NESTED_WINDOW_PLAN);
  bool                periodicCheckpointChecked = false;
  bool                wasDrainingWal = pContext->drainingWalCheckpoint;

  TAOS_CHECK_RETURN(pContext->walStallError);
  if (pContext->pWalCheckpointWaits) stRealtimeContextFinishWalCheckpoint(pContext, now);
  if (pContext->timeAlignRestart) return 0;
  TAOS_CHECK_RETURN(stDriveTimeAlignWalCheckRetries(pContext, now));
  if (pContext->timeAlignRestart) return 0;
  if (tSimpleHashGetSize(pTask->timeAlignCloses.byOperation)) {
    code = stDriveTimeAlignCloses(pTask, pContext->sessionId, now);
    QUERY_CHECK_CODE(code, lino, _end);
    int32_t          iter = 0;
    STimeAlignClose *close = NULL;
    while (pContext->timeAlignAbortedRound &&
           (close = tSimpleHashIterate(pTask->timeAlignCloses.byOperation, close, &iter))) {
      if (close->roundId == pContext->timeAlignAbortedRound) goto _end;
    }
  }
  pContext->timeAlignAbortedRound = 0;
  if (nested && stUsesTimeAlignRows(pTask) && !pContext->suppressOutput) {
    TAOS_CHECK_RETURN(stAcceptAlignedChain(pContext));
    if (atomic_load_32(&pTask->alignedCheckpointHold)) TAOS_CHECK_RETURN(stRetireCancelledAlignedFollowers(pContext));
  }
  if (atomic_load_32(&pTask->timeAlignRepairs) > 0) {
    return stTriggerTaskAddWaitSession(pTask, pContext->sessionId, taosGetTimestampNs() + STREAM_TRIGGER_IDLE_TIME_NS);
  }
  if (pContext->timeAlignRound && pContext->boundDetermined && pContext->status != STRIGGER_CONTEXT_DETERMINE_BOUND &&
      (listNEles(&pContext->groupsToCheck) || pContext->pMinGroup || pContext->calcParamPool.size ||
       pContext->nestedPendingParamCount || pContext->pCalcReq || pContext->timeAlignValidation.operation)) {
    bool waiting = false;
    TAOS_CHECK_RETURN(stValidateTimeAlignRound(pTask, pContext->sessionId, pContext->timeAlignRound,
                                               &pContext->timeAlignValidation, &waiting));
    if (waiting) return 0;
  }
  stTriggerTaskApplyPrevWindowUpdates(pTask, false);

  stTriggerTaskShrinkCalcParamPool(pTask, &pContext->calcParamPool, &pContext->lastCalcParamPoolShrinkMonoUs,
                                   checkStartMonoUs, pContext->sessionId);

  if (nested && !pContext->suppressOutput) {
    stTriggerTaskSweepRetiredNestedRecoveries(pTask);
    if (!periodicCheckpointChecked && pTask->nestedRecoveryError == TSDB_CODE_SUCCESS && pContext->haveReadCheckpoint &&
        (pTask->pendingPeriodicCheckpoint || stTriggerTaskHasNestedRecoveryOwner(pTask))) {
      stTriggerTaskGeneratePeriodicCheckpoint(pTask, pContext, now);
      periodicCheckpointChecked = true;
    }
    QUERY_CHECK_CODE(pTask->nestedRecoveryError, lino, _end);
    if (pContext->haveReadCheckpoint && pTask->pNestedRecovery != NULL) {
      SSTriggerNestedRecovery *pRecovery = pTask->pNestedRecovery;
      code = stTriggerTaskDriveNestedReplay(pTask, pRecovery, now);
      if (code != TSDB_CODE_SUCCESS && pTask->pNestedRecovery == pRecovery) {
        code = stTriggerTaskAbortNestedRecovery(pTask, pRecovery, code);
        stTriggerTaskSweepRetiredNestedRecoveries(pTask);
      }
      QUERY_CHECK_CODE(code, lino, _end);
      goto _end;
    }
  }

  if (pContext->pPeriod != NULL) {
    code = stRealtimePeriodPoll(pContext, now);
    QUERY_CHECK_CODE(code, lino, _end);
    if (pContext->pPeriod->pDispatch != NULL && stRealtimePeriodHasExtPulls(pContext)) goto _end;
  }

  if (listNEles(&pContext->retryPullReqs) > 0) {
    // Each missing-reader re-send waits for its own deadline, so a later failure cannot be pushed out by
    // the timer that was armed for an earlier one.
    int64_t    earliestDue = INT64_MAX;
    SListNode *pNode = TD_DLIST_HEAD(&pContext->retryPullReqs);
    while (pNode != NULL) {
      SListNode            *pNext = TD_DLIST_NODE_NEXT(pNode);
      SSTriggerPullRequest *pReq = *(SSTriggerPullRequest **)pNode->data;
      if (pReq->retryDueNs > taosGetMonoTimestampNs()) {
        if (pReq->retryDueNs < earliestDue) earliestDue = pReq->retryDueNs;
      } else {
        code = stRealtimeContextRetryPullRequest(pContext, pNode, pReq);
        QUERY_CHECK_CODE(code, lino, _end);
      }
      pNode = pNext;
    }
    if (earliestDue != INT64_MAX) {
      code = stTriggerTaskAddWaitSessionForReason(pTask, pContext->sessionId, earliestDue,
                                                  STREAM_TRIGGER_WAIT_PULL_RETRY);
      QUERY_CHECK_CODE(code, lino, _end);
    }
    goto _end;
  }

  if (pContext->calcGroupValueMisses || pContext->notifyGroupColValuePending ||
      (wasDrainingWal && stRealtimeContextHasPendingWalPulls(pContext)))
    goto _end;

  // Group-value replies and slot releases normally advance virtual output precreation.
  if (pTask->isVirtualTable && pContext->status == STRIGGER_CONTEXT_DETERMINE_BOUND &&
      taosArrayGetSize(pContext->pPendingCreateTableGids) > 0) {
    SSTriggerPendingCreateTableEntry *pEntry =
        taosArrayGet(pContext->pPendingCreateTableGids, pContext->pendingCreateTableIndex);
    if (pEntry->retryAt == 0 || pEntry->retryAt > now) goto _end;
    code = stRealtimeContextSubmitPendingCreateTable(pContext, pEntry);
    QUERY_CHECK_CODE(code, lino, _end);
    if (pContext->status == STRIGGER_CONTEXT_DETERMINE_BOUND) goto _end;
  }

  // A matured deferred group owns local work that can be dispatched even when a
  // WAL pull is still in flight.  Allow this case to proceed; the tail of this
  // function guards against issuing a duplicate WAL pull.
  bool hasReadyDeferredGroup = false;
  bool hasDueDeferredGroup = false;
  bool hasRunningReq = false;
  if (pContext->pMaxDelayHeap != NULL && pContext->pMaxDelayHeap->min != NULL) {
    SSTriggerRealtimeGroup *pMinG =
        container_of(pContext->pMaxDelayHeap->min, SSTriggerRealtimeGroup, heapNode);
    int64_t pending = nested ? listNEles(&pMinG->pendingNestedParWinEvents) + listNEles(&pMinG->pendingNestedEvents)
                             : pMinG->pPendingCalcParams.neles + pMinG->pPendingParWinCalcParams.neles;
    if (pMinG->nextExecTime <= now) {
      hasDueDeferredGroup = true;
    }
    if (pMinG->nextExecTime <= now && pending > 0) {
      hasReadyDeferredGroup = true;
      stDebug("[ext-bypass] deferred group gid=%" PRId64 " matured, nextExecTime=%" PRId64 " now=%" PRId64
              ", pendingParams:%" PRId64 ", pendingParWinParams:%" PRId64 ", fall through to dispatch calc",
              pMinG->gid, pMinG->nextExecTime, now, pMinG->pPendingCalcParams.neles,
              pMinG->pPendingParWinCalcParams.neles);
    }
  }

  bool dropReady = false;
  if (taosArrayGetSize(pContext->groupsToDelete) > 0) {
    int64_t nRunningReq = 0;
    code = stTriggerTaskGetRunningReq(pTask, pContext->sessionId, &nRunningReq);
    QUERY_CHECK_CODE(code, lino, _end);
    hasRunningReq = (nRunningReq > 0);
    dropReady = !hasRunningReq && pContext->pCalcReq == NULL && (!nested || pContext->nestedPendingParamCount == 0);
  }

  if (stRealtimeContextHasPendingWalPulls(pContext) &&
      !dropReady &&
      (!hasDueDeferredGroup || stTriggerTaskNeedGroupColVals(pTask, true) ||
       stRealtimeContextHasPendingWalCalcPulls(pContext))) {
    ST_TASK_DLOG("wal: defer realtime check until in-flight WAL pull responses arrive, status:%d", pContext->status);
    goto _end;
  }

  if (pContext->status == STRIGGER_CONTEXT_IDLE && pTask->isVirtualTable && !pTask->virTableInfoReady) {
    pContext->status = STRIGGER_CONTEXT_GATHER_VTABLE_INFO;
    if (taosArrayGetSize(pTask->readerList) > 0) {
      bool pullVtableInfo = (taosArrayGetSize(pTask->pVirTableInfoRsp) == 0);
      for (pContext->curReaderIdx = 0; pContext->curReaderIdx < TARRAY_SIZE(pTask->readerList);
           pContext->curReaderIdx++) {
        code = stRealtimeContextSendPullReq(pContext,
                                            pullVtableInfo ? STRIGGER_PULL_VTABLE_INFO : STRIGGER_PULL_OTABLE_INFO);
        QUERY_CHECK_CODE(code, lino, _end);
      }
    }
    goto _end;
  }

  if (!pContext->haveReadCheckpoint) {
    stDebug("[checkpoint] read checkpoint for stream %" PRIx64, pTask->task.streamId);
    int8_t syncState = atomic_load_8(&pTask->checkpointSyncState);
    QUERY_CHECK_CONDITION(syncState != STREAM_CHECKPOINT_SYNC_CORRUPTED, code, lino, _end, TSDB_CODE_FILE_CORRUPTED);
    if (syncState == STREAM_CHECKPOINT_SYNC_READY) {
      void   *buf = NULL;
      int64_t len = 0;
      code = streamReadCheckPoint(pTask->task.streamId, &buf, &len);
      if (code != TSDB_CODE_SUCCESS) {
        taosMemoryFree(buf);
        QUERY_CHECK_CODE(code, lino, _end);
      }
      code = stTriggerTaskParseCheckpoint(pTask, buf, len);
      if (code != TSDB_CODE_SUCCESS) {
        taosMemoryFree(buf);
        QUERY_CHECK_CODE(code, lino, _end);
      }
      taosMemoryFree(buf);
      pContext->haveReadCheckpoint = true;
    } else {
      // Retry only after a response failed to persist; pending requests must finish first.
      if (syncState == STREAM_CHECKPOINT_SYNC_RETRY) {
        SEpSet *epSet = gStreamMgmt.getSynEpset(pTask->leaderSnodeId);
        QUERY_CHECK_NULL(epSet, code, lino, _end, TSDB_CODE_SNODE_NOT_FOUND);
        if (atomic_val_compare_exchange_8(&pTask->checkpointSyncState, STREAM_CHECKPOINT_SYNC_RETRY,
                                          STREAM_CHECKPOINT_SYNC_PENDING) == STREAM_CHECKPOINT_SYNC_RETRY) {
          code = streamSyncWriteCheckpoint(pTask->task.streamId, epSet, NULL, 0);
          QUERY_CHECK_CODE(code, lino, _end);
        }
      }
      // Wait 1 second before checking readiness again.
      int64_t resumeTime = now + 1 * NANOSECOND_PER_SEC;
      code = stTriggerTaskAddWaitSession(pTask, pContext->sessionId, resumeTime);
      QUERY_CHECK_CODE(code, lino, _end);
      goto _end;
    }
  }

  TAOS_CHECK_RETURN(stRestoreCheckpointOrdinary(pContext));
  TAOS_CHECK_RETURN(stRestoreAlignedRepairs(pContext));

  bool periodPatchBusy = false;
  if (IS_PATCHING_VITRUAL_TABLE(pContext) && pContext->pPeriod != NULL) {
    int32_t               iter = 0;
    SSTriggerPeriodInput *pInput = tSimpleHashIterate(pContext->pPeriod->pInputs, NULL, &iter);
    while (pInput != NULL) {
      SSTriggerPeriodReader *pReader =
          tSimpleHashGet(pInput->pCycle->pReaders, &pInput->address.nodeId, sizeof(int32_t));
      periodPatchBusy = periodPatchBusy || pInput->inFlight || pReader->pendingToken != 0;
      pInput = tSimpleHashIterate(pContext->pPeriod->pInputs, pInput, &iter);
    }
    // Let the active calculation drain without overwriting its shared status with GATHER_VTABLE_INFO.
    bool dispatchBusy = pContext->pPeriod->pDispatch != NULL && !pContext->pPeriod->dispatchDone;
    if (periodPatchBusy && !dispatchBusy) goto _end;
    periodPatchBusy = periodPatchBusy || dispatchBusy;
  }
  bool finishingAlignCalc = pContext->timeAlignRound && pContext->pCalcReq;
  if (IS_PATCHING_VITRUAL_TABLE(pContext) && !periodPatchBusy && !finishingAlignCalc) {
    // The old cut covers the old physical table set. Drain its dispatched results
    // before releasing it, then admit a cut including the replacement bindings.
    if (pContext->timeAlignRound) {
      int64_t outstanding = 0;
      code = stTriggerTaskGetRunningReq(pTask, pContext->sessionId, &outstanding);
      QUERY_CHECK_CODE(code, lino, _end);
      if (outstanding) {
        code = stTriggerTaskAddWaitSession(pTask, pContext->sessionId, now + STREAM_TRIGGER_IDLE_TIME_NS);
      } else if (!stRealtimeContextHasPendingWalPulls(pContext)) {
        code = stDropTimeAlignBoundary(pContext, true);
      }
      QUERY_CHECK_CODE(code, lino, _end);
      goto _end;
    }
    int64_t waitingReqId = atomic_load_64(&pTask->waitingMgmtReqId);
    if (waitingReqId != -1) {
      ST_TASK_DLOG("wait virtual table patch mgmt response, reqId:%" PRId64, waitingReqId);
      goto _end;
    }
    pContext->status = STRIGGER_CONTEXT_GATHER_VTABLE_INFO;
    bool pullVtableInfo = (taosArrayGetSize(pContext->patchContext.pVirTableInfoRsp) == 0);
    if (pullVtableInfo) {
      code = stRealtimeContextPrepareVtablePatch(pContext);
      if (code != TSDB_CODE_SUCCESS) {
        // Retries a short transient streak, then records a task-level failure and clears the round.
        code = stRealtimeContextHandleVtablePatchPrepareFailure(pContext, code);
        QUERY_CHECK_CODE(code, lino, _end);
        // The round is gone and the task is failing, so there is nothing left to pull table info for.
        if (!IS_PATCHING_VITRUAL_TABLE(pContext)) {
          goto _end;
        }
      }
    }
    ST_TASK_DLOG("continue virtual table patch, pullVtableInfo:%d", pullVtableInfo);
    for (pContext->curReaderIdx = 0; pContext->curReaderIdx < TARRAY_SIZE(pTask->readerList);
         pContext->curReaderIdx++) {
      code = stRealtimeContextSendPullReq(pContext,
                                          pullVtableInfo ? STRIGGER_PULL_VTABLE_INFO : STRIGGER_PULL_OTABLE_INFO);
      QUERY_CHECK_CODE(code, lino, _end);
    }
    goto _end;
  }

  if (pTask->isVirtualTable && stRealtimeContextHasExtProgress(pContext) &&
      (!pTask->virTableInfoReady || !stTriggerTaskExtBindingsReady(pTask->pExtOrigTableRefs))) {
    ST_TASK_DLOG("defer realtime data pull until external registry binding is ready, vtableReady:%d, entries:%d",
                 pTask->virTableInfoReady, (int32_t)TARRAY_SIZE(pTask->pExtOrigTableRefs));
    goto _end;
  }

  if (nested && !pContext->suppressOutput) {
    stTriggerTaskSweepRetiredNestedRecoveries(pTask);
    if (!periodicCheckpointChecked && pTask->nestedRecoveryError == TSDB_CODE_SUCCESS && pContext->haveReadCheckpoint &&
        (pTask->pendingPeriodicCheckpoint || stTriggerTaskHasNestedRecoveryOwner(pTask))) {
      stTriggerTaskGeneratePeriodicCheckpoint(pTask, pContext, now);
      periodicCheckpointChecked = true;
    }
    QUERY_CHECK_CODE(pTask->nestedRecoveryError, lino, _end);
    if (pTask->pNestedRecovery != NULL) {
      SSTriggerNestedRecovery *pRecovery = pTask->pNestedRecovery;
      code = stTriggerTaskDriveNestedReplay(pTask, pRecovery, now);
      if (code != TSDB_CODE_SUCCESS && pTask->pNestedRecovery == pRecovery) {
        code = stTriggerTaskAbortNestedRecovery(pTask, pRecovery, code);
        stTriggerTaskSweepRetiredNestedRecoveries(pTask);
      }
      QUERY_CHECK_CODE(code, lino, _end);
      goto _end;
    }
  }

  // P3 (d2): EXT PULL sub-loop for federated streams. Bypasses all WAL PULL paths,
  // UNLESS:
  //   a) groups are already queued for calc (DATA_EXT has arrived and populated
  //      groupsToCheck)  -  fall through to the _check: loop first.
  //   b) status is SEND_CALC_REQ  -  a CALC_DATA_EXT response just arrived and the
  //      pMinGroup calc loop must resume to write data to cache and send the runner
  //      request.  Skip the EXT short-circuit so pMinGroup is processed below.
  //   c) any ext reader has a pending pCalcUidWindow  -  CALC_DATA_EXT has not been
  //      sent yet (deferred calc path); fall through so stRealtimeContextSendCalcReq
  //      can dispatch CALC_DATA_EXT.  Without this check, the bypass fires on every
  //      session resume and the pCalcUidWindow is never consumed.
  //   d) a deferred group in pMaxDelayHeap has matured (nextExecTime <= now) and
  //      has pending calc params  -  EXT SLIDING streams batch-delay their dispatch
  //      via the heap; if we always bypass here those groups are never processed.
  bool hasWalProgress = stRealtimeContextHasWalProgress(pContext);
  bool hasExtProgress = stRealtimeContextHasExtProgress(pContext);
  bool hasCalcUidWindow = false;
  if (hasExtProgress) {
    int32_t               cwIter = 0;
    SSTriggerExtProgress **ppCW =
        (SSTriggerExtProgress **)tSimpleHashIterate(pContext->pReaderExtProgress, NULL, &cwIter);
    while (ppCW != NULL) {
      if ((*ppCW)->pCalcUidWindow != NULL) {
        hasCalcUidWindow = true;
        break;
      }
      ppCW = (SSTriggerExtProgress **)tSimpleHashIterate(pContext->pReaderExtProgress, ppCW, &cwIter);
    }
  }
  // e) PERIOD trigger with !ignoreNoDataTrigger must fire on a wall-clock schedule
  //    regardless of whether the ext source ever returns new rows. Left unguarded, this
  //    bypass re-dispatches to stRealtimeContextCheckExt on every session resume forever
  //    (groupsToCheck never becomes non-empty for a source with no new rows), so PERIOD
  //    would never reach the periodWindow.ekey force-fire logic further down in this
  //    function. Skip the bypass for this trigger/option combination so control always
  //    falls through to that logic instead. Gated on boundDetermined so the initial
  //    LAST_TS_EXT bootstrap (which this same bypass also dispatches, before
  //    boundDetermined flips true) is left untouched.
  bool isForcedPeriod =
      (pTask->triggerType == STREAM_TRIGGER_PERIOD && !pTask->ignoreNoDataTrigger && pContext->boundDetermined);
  if (isForcedPeriod) {
    stDebug(
        "[ext-bypass] isForcedPeriod, skip stRealtimeContextCheckExt bypass so control "
        "falls through to the periodWindow.ekey force-fire logic instead");
  }
  if (hasExtProgress &&
      !hasWalProgress &&
      TD_DLIST_NELES(&pContext->groupsToCheck) == 0 &&
      pContext->status != STRIGGER_CONTEXT_SEND_CALC_REQ &&
      !hasCalcUidWindow &&
      !hasReadyDeferredGroup &&
      !isForcedPeriod) {
    code = stRealtimeContextCheckExt(pContext, now);
    QUERY_CHECK_CODE(code, lino, _end);
    goto _end;
  }

  if (pContext->status == STRIGGER_CONTEXT_IDLE) {
    if ((hasWalProgress || hasExtProgress) &&
        (!pContext->boundDetermined || (stUsesTimeAlignRows(pTask) && !pContext->timeAlignRound))) {
      pContext->status = STRIGGER_CONTEXT_DETERMINE_BOUND;
      if (hasWalProgress && stUsesTimeAlignRows(pTask)) {
        pContext->timeAlignRound = stNextTimeAlignId(pTask);
        pContext->timeAlignBoundsPending = tSimpleHashGetSize(pContext->pReaderWalProgress);
      }
      if (hasWalProgress) {
        for (pContext->curReaderIdx = 0; pContext->curReaderIdx < TARRAY_SIZE(pTask->readerList);
             pContext->curReaderIdx++) {
          code = stRealtimeContextSendPullReq(pContext, STRIGGER_PULL_LAST_TS);
          if (code) {
            code = stAbortIdleAlignedPoll(pContext, code);
            goto _end;
          }
        }
      }
      if (hasExtProgress) {
        code = stRealtimeContextCheckExt(pContext, now);
        QUERY_CHECK_CODE(code, lino, _end);
      }
      goto _end;
    }

    if (!pTask->historyCalcStarted) {
      QUERY_CHECK_CONDITION(pTask->pHistoryContext == NULL, code, lino, _end, TSDB_CODE_INVALID_PARA);
      pTask->pHistoryContext = taosMemoryCalloc(1, sizeof(SSTriggerHistoryContext));
      QUERY_CHECK_NULL(pTask->pHistoryContext, code, lino, _end, terrno);
      code = stHistoryContextInit(pTask->pHistoryContext, pTask);
      QUERY_CHECK_CODE(code, lino, _end);
      SSTriggerCtrlRequest req = {.type = STRIGGER_CTRL_START,
                                  .streamId = pTask->task.streamId,
                                  .taskId = pTask->task.taskId,
                                  .sessionId = pTask->pHistoryContext->sessionId};
      SRpcMsg              msg = {.msgType = TDMT_STREAM_TRIGGER_CTRL};
      msg.contLen = tSerializeSTriggerCtrlRequest(NULL, 0, &req);
      QUERY_CHECK_CONDITION(msg.contLen > 0, code, lino, _end, TSDB_CODE_INTERNAL_ERROR);
      msg.pCont = rpcMallocCont(msg.contLen);
      QUERY_CHECK_NULL(msg.pCont, code, lino, _end, terrno);
      int32_t tlen = tSerializeSTriggerCtrlRequest(msg.pCont, msg.contLen, &req);
      QUERY_CHECK_CONDITION(tlen == msg.contLen, code, lino, _end, TSDB_CODE_INTERNAL_ERROR);
      TRACE_SET_ROOTID(&msg.info.traceId, pTask->task.streamId);
      TRACE_SET_MSGID(&msg.info.traceId, tGenIdPI64());

      SMsgCb *pCb = &gStreamMgmt.msgCb;
      code = pCb->putToQueueFp(pCb->mgmt, STREAM_TRIGGER_QUEUE, &msg);
      QUERY_CHECK_CODE(code, lino, _end);

      ST_TASK_DLOG("send start control request for session: %" PRIx64, req.sessionId);
      ST_TASK_DLOG("control request 0x%" PRIx64 ":0x%" PRIx64 " sent", msg.info.traceId.rootId, msg.info.traceId.msgId);
      pTask->historyCalcStarted = true;

      if (pTask->fillHistory && !pTask->historyFinished) {
        code = stTriggerTaskAddRecalcRequest(pTask, NULL, NULL, true, false, false, 0);
        QUERY_CHECK_CODE(code, lino, _end);
      }
    }

    if (pTask->triggerType != STREAM_TRIGGER_PERIOD) {
      pContext->status = STRIGGER_CONTEXT_FETCH_META;
      if (hasExtProgress && !hasWalProgress) {
        /* EXT-only stream: dispatch via stRealtimeContextCheckExt, not WAL pull. */
        ST_TASK_DLOG("ext: non-period trigger, dispatching via stRealtimeContextCheckExt %s", "");
        code = stRealtimeContextCheckExt(pContext, now);
        QUERY_CHECK_CODE(code, lino, _end);
        goto _end;
      }
      if (hasWalProgress) {
        for (pContext->curReaderIdx = 0; pContext->curReaderIdx < TARRAY_SIZE(pTask->readerList);
             pContext->curReaderIdx++) {
          code = stRealtimeContextSendPullReq(pContext, (pContext->walMode == STRIGGER_WAL_META_WITH_DATA)
                                                            ? STRIGGER_PULL_WAL_META_DATA_NEW
                                                            : STRIGGER_PULL_WAL_META_NEW);
          if (code) {
            code = stAbortIdleAlignedPoll(pContext, code);
            goto _end;
          }
        }
      }
      if (hasExtProgress) {
        ST_TASK_DLOG("ext: mixed non-period trigger, dispatching external meta pulls %s", "");
        code = stRealtimeContextCheckExt(pContext, now);
        QUERY_CHECK_CODE(code, lino, _end);
      }
      goto _end;
    }

    if (hasWalProgress) {
      code = stRealtimePeriodPoll(pContext, now);
      QUERY_CHECK_CODE(code, lino, _end);
      bool ready = false;
      code = stRealtimePeriodDispatch(pContext, now, &ready);
      QUERY_CHECK_CODE(code, lino, _end);
      if (!ready) goto _end;
      goto _check;
    }

    // check if to start for period trigger
    if (pContext->periodWindow.skey == INT64_MIN) {
      pContext->periodWindow = stTriggerTaskGetTimeWindow(pTask, now);
    }
    if (now >= pContext->periodWindow.ekey) {
      pContext->status = STRIGGER_CONTEXT_FETCH_META;
      if (hasExtProgress && !hasWalProgress) {
        /* EXT-only stream: always dispatch via stRealtimeContextCheckExt, which sends
         * STRIGGER_PULL_*_EXT requests to genuinely re-poll the external source --
         * regardless of ignoreNoDataTrigger. The "fire on schedule even with no
         * new data" semantics is handled inside stRealtimeContextProcExtPullRsp's
         * empty-poll exits (via stRealtimeContextForcePeriodGroupsToCheck), not
         * here, so a source with no new rows still gets probed every tick instead
         * of being skipped forever. */
        ST_TASK_DLOG("ext: period window ekey reached, dispatching via stRealtimeContextCheckExt %s", "");
        code = stRealtimeContextCheckExtImpl(pContext, now, true);
        QUERY_CHECK_CODE(code, lino, _end);
        goto _end;
      }
      if (hasWalProgress) {
        // fetch wal meta from all readers
        for (pContext->curReaderIdx = 0; pContext->curReaderIdx < TARRAY_SIZE(pTask->readerList);
             pContext->curReaderIdx++) {
          code = stRealtimeContextSendPullReq(pContext, STRIGGER_PULL_WAL_META_NEW);
          QUERY_CHECK_CODE(code, lino, _end);
        }
        if (hasExtProgress) {
          ST_TASK_DLOG("ext: mixed period trigger, dispatching external meta pulls %s", "");
          code = stRealtimeContextCheckExt(pContext, now);
          QUERY_CHECK_CODE(code, lino, _end);
        }
        goto _end;
      } else {
        // No trigger table at all (pure wall-clock PERIOD, no FROM clause): force
        // the default group so PERIOD still fires on schedule.
        ST_TASK_DLOG("period: no trigger table (readerList empty, not ext), forcing default group %s", "");
        code = stRealtimeContextForcePeriodGroupsToCheck(pContext);
        QUERY_CHECK_CODE(code, lino, _end);
      }
    } else {
      QUERY_CHECK_CONDITION(TD_DLIST_NELES(&pContext->groupsToCheck) == 0, code, lino, _end, TSDB_CODE_INVALID_PARA);
      code = stTriggerTaskAddWaitSession(pTask, pContext->sessionId, pContext->periodWindow.ekey);
      QUERY_CHECK_CODE(code, lino, _end);
      goto _end;
    }
  }

  if (pContext->pPeriod == NULL && pContext->needAlignWalForExtTrigger && hasWalProgress &&
      TD_DLIST_NELES(&pContext->groupsToCheck) > 0 && pContext->status == STRIGGER_CONTEXT_FETCH_META) {
    pContext->needAlignWalForExtTrigger = false;
    ST_TASK_DLOG("ext: align mixed WAL trigger data before checking groups:%" PRId64,
                 (int64_t)TD_DLIST_NELES(&pContext->groupsToCheck));
    for (pContext->curReaderIdx = 0; pContext->curReaderIdx < TARRAY_SIZE(pTask->readerList);
         pContext->curReaderIdx++) {
      code = stRealtimeContextSendPullReq(pContext, (pContext->walMode == STRIGGER_WAL_META_WITH_DATA)
                                                        ? STRIGGER_PULL_WAL_META_DATA_NEW
                                                        : STRIGGER_PULL_WAL_META_NEW);
      QUERY_CHECK_CODE(code, lino, _end);
    }
    goto _end;
  }

_check:
  if (pContext->pPeriod != NULL && pContext->pPeriod->pDispatch != NULL && !pContext->pPeriod->idleChecked) {
    code = stRealtimeContextCheckIdleGroup(pContext, now);
    QUERY_CHECK_CODE(code, lino, _end);
    if (pContext->notifyGroupColValuePending) goto _end;
    pContext->pPeriod->idleChecked = true;
  }
  while (TD_DLIST_NELES(&pContext->groupsToCheck) > 0 && pContext->status != STRIGGER_CONTEXT_ACQUIRE_REQUEST &&
         pContext->status != STRIGGER_CONTEXT_SEND_CALC_REQ) {
    SSTriggerRealtimeGroup *pGroup = TD_DLIST_HEAD(&pContext->groupsToCheck);
    if (pGroup->alignedCatchupId && !stHasReadyAlignedRepair(pTask, pGroup->alignedCatchupId)) {
      pGroup->alignedCatchupId = 0;
      pGroup->alignedDraining = false;
      stUpdateAlignedWorkGroup(pGroup);
    }
    // Keep this page in the ordinary Reader buffers while history finishes the correction.
    // Other groups on the page can run before the next multi-vgroup poll.
    bool waitingRepair = !pContext->suppressOutput && !pGroup->alignedDraining && !pGroup->alignedNormalPage &&
                         (pGroup->alignedCatchupId ||
                          (pGroup->alignedRepairId && stHasReadyAlignedRepair(pTask, pGroup->alignedRepairId)));
    if (waitingRepair || (pGroup->alignedNormalPage && stAlignedNormalPageWaiting(pGroup->alignedNormalPage))) {
      TD_DLIST_POP(&pContext->groupsToCheck, pGroup);
      TD_DLIST_APPEND(&pContext->groupsToCheck, pGroup);
      if (++waitingGroups >= TD_DLIST_NELES(&pContext->groupsToCheck)) break;
      continue;
    }
    if (pTask->pTimeAlign && stUsesTimeAlignRows(pTask) && !pGroup->seedAdmission.ready) {
      code = stRealtimeGroupAdmitTimeAlignSeeds(pGroup);
      QUERY_CHECK_CODE(code, lino, _end);
      if (!pGroup->seedAdmission.ready) {
        if (pContext->pRecovery) pContext->timeAlignWaiting = true;
        TD_DLIST_POP(&pContext->groupsToCheck, pGroup);
        TD_DLIST_APPEND(&pContext->groupsToCheck, pGroup);
        if (++waitingGroups >= TD_DLIST_NELES(&pContext->groupsToCheck)) break;
        continue;
      }
    }
    waitingGroups = 0;
    bool                    notifyNameReady = false;
    code = stRealtimeContextPrepareNotifyName(pContext, pGroup, &notifyNameReady);
    QUERY_CHECK_CODE(code, lino, _end);
    if (!notifyNameReady) goto _end;
    if (nested) {
      if (!pContext->suppressOutput && pContext->nestedPendingParamCount >= tsStreamTriggerMaxPendingParams) {
        break;
      }
      QUERY_CHECK_CONDITION(
          pContext->status == STRIGGER_CONTEXT_FETCH_META || pContext->status == STRIGGER_CONTEXT_CHECK_CONDITION, code,
          lino, _end, TSDB_CODE_INTERNAL_ERROR);
      pContext->status = STRIGGER_CONTEXT_CHECK_CONDITION;
      pContext->timeAlignWaiting = false;
      code = stRealtimeGroupDriveNestedInputs(pGroup, now);
      QUERY_CHECK_CODE(code, lino, _end);
      if (pContext->timeAlignWaiting) goto _end;
      if (pGroup->nestedInputRegistered) {
        if (pGroup->alignedNormalPage && stAlignedNormalPageWaiting(pGroup->alignedNormalPage)) {
          TD_DLIST_POP(&pContext->groupsToCheck, pGroup);
          TD_DLIST_APPEND(&pContext->groupsToCheck, pGroup);
          continue;
        }
        goto _end;
      }
      code = stRealtimeGroupCompleteNestedCheck(pGroup);
      QUERY_CHECK_CODE(code, lino, _end);
      if (!pContext->suppressOutput &&
          listNEles(&pGroup->pendingNestedParWinEvents) + listNEles(&pGroup->pendingNestedEvents) >=
              STREAM_CALC_REQ_MAX_WIN_NUM) {
        break;
      }
      continue;
    }
    switch (pContext->status) {
      case STRIGGER_CONTEXT_FETCH_META: {
        pContext->status = STRIGGER_CONTEXT_CHECK_CONDITION;
      }
      case STRIGGER_CONTEXT_CHECK_CONDITION: {
        bool durationsReady = false;
        code = stRealtimeGroupEnsureDurationsFrozen(pContext, pGroup, &durationsReady);
        QUERY_CHECK_CODE(code, lino, _end);
        if (!durationsReady) {
          goto _end;
        }
        if (pTask->triggerType == STREAM_TRIGGER_SLIDING && pContext->dumpTableUids.neles == 0) {
          // Preserve the complete list across pseudo-column pulls; tableUids holds only the unprocessed suffix.
          code = stRealtimeContextCopyTableUids(pContext, &pGroup->tableUids, &pContext->dumpTableUids);
          QUERY_CHECK_CODE(code, lino, _end);
        }
        pContext->timeAlignWaiting = false;
        code = stRealtimeGroupCheck(pGroup);
        QUERY_CHECK_CODE(code, lino, _end);
        if (pContext->timeAlignWaiting) goto _end;
        if (pContext->needPseudoCols) {
          code = stRealtimeContextSendPullReq(pContext, STRIGGER_PULL_VTABLE_PSEUDO_COL);
          QUERY_CHECK_CODE(code, lino, _end);
          pContext->needPseudoCols = false;
          goto _end;
        }

        // Rebuild the saved request once this input has restored the window and its pending output.
        SFirstCloseRepair *repair = tSimpleHashGet(pTask->pFirstCloseRepairs, &pGroup->gid, sizeof(pGroup->gid));
        if (repair && repair->needsReplay && pGroup->newThreshold >= repair->frontier) {
          code = stSubmitFirstCloseRepair(pTask, pGroup, repair);
          QUERY_CHECK_CODE(code, lino, _end);
          repair->needsReplay = false;
        }

        if (taosArrayGetSize(pContext->pNotifyParams) > 0) {
          char triggerTableName[TSDB_TABLE_NAME_LEN] = {0};
          code = stTriggerTaskGetNotifyTableName(pTask, pContext->pGroupColVals, pGroup->gid, triggerTableName);
          QUERY_CHECK_CODE(code, lino, _end);
          code = streamSendNotifyContent(&pTask->task, pTask->streamName, NULL, triggerTableName, pTask->triggerType,
                                         pGroup->gid, pTask->precision, pTask->pNotifyAddrUrls, pTask->addOptions,
                                         TARRAY_DATA(pContext->pNotifyParams), TARRAY_SIZE(pContext->pNotifyParams));
          QUERY_CHECK_CODE(code, lino, _end);
          stTaskStatsRecordTriggerEvent(pTask->pStats, STREAM_TRIGGER_EVENT_NOTIFY, 1, streamTaskGetMonotonicUs());
          // A notify-only stream (no calc query) never completes a calc request, so the rolling
          // completed cutoff that protects the trigger side of a shared-reader rewind is never
          // advanced by the calc path. Advance it from the just-notified window ends: rows up to
          // the newest notified boundary were already consumed by this group's window state and
          // must not re-enter it after a restart.
          if (pTask->isVirtualTable && pTask->calcEventType == STRIGGER_EVENT_WINDOW_NONE &&
              pContext->pReaderExtProgress != NULL) {
            int64_t notifyMaxEnd = INT64_MIN;
            if (stTriggerTaskCalcParamsMaxEnd(pContext->pNotifyParams, &notifyMaxEnd)) {
              code = stRealtimeContextUpdateExtCompletedCutoffForGroup(pContext, pGroup->gid, notifyMaxEnd);
              QUERY_CHECK_CODE(code, lino, _end);
            }
          }
        }
        stRealtimeGroupClearTempState(pGroup);
        break;
      }
      default: {
        ST_TASK_ELOG("invalid context status %d at %s:%d", pContext->status, __func__, __LINE__);
        code = TSDB_CODE_INVALID_PARA;
        QUERY_CHECK_CODE(code, lino, _end);
      }
    }
    if (pGroup->pTimeAlignStates && pTask->triggerType == STREAM_TRIGGER_SLIDING)
      stTimeAlignFinishPass(pGroup->pTimeAlignStates->state, pContext->needCheckAgain);
    if (pContext->needCheckAgain && pTask->triggerType == STREAM_TRIGGER_SLIDING) {
      code = stRealtimeContextCopyTableUids(pContext, &pContext->dumpTableUids, &pGroup->tableUids);
      QUERY_CHECK_CODE(code, lino, _end);
      // The restore above bypasses the append helper; rebuild the dedup set from the
      // restored list so later appends in the same round dedup against the right set.
      if (pTask->isVirtualTable && pGroup->pSeenTableUids != NULL) {
        tSimpleHashClear(pGroup->pSeenTableUids);
        SObjListIter                 seenIter = {0};
        SSTriggerVirtualTableSliceRef *pRef = NULL;
        taosObjListInitIter(&pGroup->tableUids, &seenIter, TOBJLIST_ITER_FORWARD);
        while ((pRef = taosObjListIterNext(&seenIter)) != NULL) {
          code = tSimpleHashPut(pGroup->pSeenTableUids, pRef, sizeof(*pRef), pRef, sizeof(*pRef));
          QUERY_CHECK_CODE(code, lino, _end);
        }
      }
    } else {
      TD_DLIST_POP(&pContext->groupsToCheck, pGroup);
      stRealtimeGroupClearMetadatas(pGroup);
    }
    pContext->needCheckAgain = false;
    taosObjListClear(&pContext->dumpTableUids);
    code = stTriggerTaskReadyRecalcRequest(pTask, pGroup);
    QUERY_CHECK_CODE(code, lino, _end);
    pContext->status = STRIGGER_CONTEXT_FETCH_META;
    if (pGroup->pPendingCalcParams.neles >= STREAM_CALC_REQ_MAX_WIN_NUM ||
        pContext->calcParamPool.size >= tsStreamTriggerMaxPendingParams) {
      break;
    }
  }

  if (nested) {
    if (pContext->suppressOutput) {
      goto _end;
    }
    code = stRealtimeContextCollectNestedDelayed(pContext, now);
    QUERY_CHECK_CODE(code, lino, _end);
    code = stRealtimeContextDispatchNestedCalc(pContext, now);
    QUERY_CHECK_CODE(code, lino, _end);
    if (pContext->pNestedCalcMaterialization != NULL || pContext->status == STRIGGER_CONTEXT_ACQUIRE_REQUEST ||
        pContext->status == STRIGGER_CONTEXT_SEND_CALC_REQ) {
      goto _end;
    }
    goto _calc_done;
  }

  int64_t dispatchThrough = pContext->walCheckpointMaxDelayCutoff ? pContext->walCheckpointMaxDelayCutoff : now;
  if (pContext->pMinGroup == NULL && pContext->pMaxDelayHeap->min != NULL) {
    pContext->pMinGroup = container_of(pContext->pMaxDelayHeap->min, SSTriggerRealtimeGroup, heapNode);
    if (pContext->pMinGroup->nextExecTime > dispatchThrough &&
        !(pTask->lowLatencyCalc && (pContext->pMinGroup->pPendingCalcParams.neles > 0 ||
                                    pContext->pMinGroup->pPendingParWinCalcParams.neles > 0)) &&
        pContext->pMinGroup->pPendingCalcParams.neles < STREAM_CALC_REQ_MAX_WIN_NUM &&
        pContext->pMinGroup->pPendingParWinCalcParams.neles < STREAM_CALC_REQ_MAX_WIN_NUM &&
        pContext->calcParamPool.size < tsStreamTriggerMaxPendingParams) {
      ST_TASK_DLOG("realtime calc deferred, gid:%" PRId64 " nextExecTime:%" PRId64 " now:%" PRId64
                   " pendingParams:%" PRId64 " pendingParWinParams:%" PRId64 " keepWalPollingForIdle:%d",
                   pContext->pMinGroup->gid, pContext->pMinGroup->nextExecTime, now,
                   pContext->pMinGroup->pPendingCalcParams.neles,
                   pContext->pMinGroup->pPendingParWinCalcParams.neles,
                   hasWalProgress && pTask->idleTimeoutMs > 0);
      if ((pContext->pMinGroup->pPendingCalcParams.neles > 0 ||
           pContext->pMinGroup->pPendingParWinCalcParams.neles > 0) &&
          !(hasWalProgress && pTask->idleTimeoutMs > 0) &&
          (!hasWalProgress || pContext->catchUp || stTriggerTaskNeedGroupColVals(pTask, true))) {
        int64_t resumeTime = pContext->pMinGroup->nextExecTime;
        ST_TASK_DLOG("defer realtime calc until nextExecTime, gid:%" PRId64 ", resumeTime:%" PRId64
                     ", status:%d, groupsToCheck:%" PRId64,
                     pContext->pMinGroup->gid, resumeTime, pContext->status,
                     (int64_t)TD_DLIST_NELES(&pContext->groupsToCheck));
        pContext->pMinGroup = NULL;
        code = stTriggerTaskAddWaitSession(pTask, pContext->sessionId, resumeTime);
        QUERY_CHECK_CODE(code, lino, _end);
        goto _end;
      }
      pContext->pMinGroup = NULL;
    }
  }
  while (pContext->pMinGroup != NULL) {
    if (pContext->drainingWalCheckpoint && !pContext->pWalCheckpointWaits) {
      code = stRealtimeContextCaptureWalCheckpoint(pContext);
      QUERY_CHECK_CODE(code, lino, _end);
    }
    SSTriggerRealtimeGroup *pGroup = pContext->pMinGroup;
    if (pContext->pCalcReq == NULL && taosArrayGetSize(pTask->runnerList) == 0) {
      heapRemove(pContext->pMaxDelayHeap, &pGroup->heapNode);
      pGroup->nextExecTime = 0;
      pContext->pMinGroup = pContext->pMaxDelayHeap->min == NULL
                                ? NULL
                                : container_of(pContext->pMaxDelayHeap->min, SSTriggerRealtimeGroup, heapNode);
      continue;
    }
    if (pTask->multiGroupBatch) {
      bool completeRoute =
          (pContext->pPeriod != NULL || (pGroup->pWalMetas != NULL && tSimpleHashGetSize(pGroup->pWalMetas) > 0)) &&
          pTask->readerList != NULL && taosArrayGetSize(pTask->readerList) > 0;
      if (stTriggerTaskNeedGroupColVals(pTask, true)) {
        void *px = tSimpleHashGet(pContext->pGroupColVals, &pGroup->gid, sizeof(pGroup->gid));
        if (px == NULL || (*(SArray **)px == NULL && stTriggerTaskCanDrainWalCheckpoint(pTask))) {
          pContext->status = STRIGGER_CONTEXT_SEND_CALC_REQ;
          code = stRealtimeContextSendGroupColValuePull(pContext, pGroup->gid);
          QUERY_CHECK_CODE(code, lino, _end);
          goto _end;
        }
        if (*(SArray **)px == NULL) {
          heapRemove(pContext->pMaxDelayHeap, &pGroup->heapNode);
          pGroup->nextExecTime = 0;
          pContext->pMinGroup = NULL;
          pContext->status = STRIGGER_CONTEXT_FETCH_META;
          continue;
        }
      }

      SSTriggerGroupCalcInfo *pGroupCalc = NULL;
      if (pContext->pCalcReq == NULL) {
        if ((pTask->placeHolderBitmap & PLACE_HOLDER_PARTITION_ROWS) != 0 &&
            stRealtimeCalcGroupIsRunning(pTask, pContext->sessionId, pGroup->gid)) {
          pContext->status = STRIGGER_CONTEXT_ACQUIRE_REQUEST;
          goto _end;
        }
        code = stTriggerTaskAcquireRequest(pTask, pContext->sessionId, pGroup->gid, &pContext->pCalcReq);
        QUERY_CHECK_CODE(code, lino, _end);
        if (pContext->pCalcReq == NULL) {
          if (pTask->lowLatencyCalc || pContext->calcParamPool.size >= tsStreamTriggerMaxPendingParams) {
            pContext->status = STRIGGER_CONTEXT_ACQUIRE_REQUEST;
            goto _end;
          }
          pContext->status = STRIGGER_CONTEXT_FETCH_META;
          pContext->pMinGroup = NULL;
          continue;
        }
        code = stTriggerTaskInitCalcRequestGroup(pContext->pCalcReq, pGroup->gid, pContext->pCalcReq->createTable,
                                                 &pGroupCalc);
        QUERY_CHECK_CODE(code, lino, _end);
      } else {
        int32_t requestCount = 0;
        code = stTriggerTaskCalcRequestParamCount(pContext->pCalcReq, &requestCount);
        QUERY_CHECK_CODE(code, lino, _end);
        if (!completeRoute && requestCount > 0 &&
            tSimpleHashGet(pContext->pCalcReq->pGroupCalcInfos, &pGroup->gid, sizeof(pGroup->gid)) == NULL) {
          code = stRealtimeContextFlushCalcRequest(pContext);
          QUERY_CHECK_CODE(code, lino, _end);
          pContext->status = STRIGGER_CONTEXT_FETCH_META;
          pContext->pMinGroup = NULL;
          continue;
        }
        bool reserved = false;
        code = stTriggerTaskTryReserveCalcRequestGroup(pTask, pContext->pCalcReq, pGroup->gid, &pGroupCalc, &reserved);
        QUERY_CHECK_CODE(code, lino, _end);
        if (!reserved) {
          if (requestCount > 0) {
            code = stRealtimeContextFlushCalcRequest(pContext);
          } else {
            code = stTriggerTaskReleaseRequest(pTask, &pContext->pCalcReq, false);
          }
          QUERY_CHECK_CODE(code, lino, _end);
          pContext->status = STRIGGER_CONTEXT_FETCH_META;
          pContext->pMinGroup = NULL;
          continue;
        }
      }

      int32_t requestCount = 0;
      code = stTriggerTaskCalcRequestParamCount(pContext->pCalcReq, &requestCount);
      QUERY_CHECK_CODE(code, lino, _end);
      int32_t appended = 0;
      code =
          stRealtimeGroupAppendPendingCalc(pGroup, pGroupCalc, STREAM_CALC_REQ_MAX_WIN_NUM - requestCount, &appended);
      QUERY_CHECK_CODE(code, lino, _end);
      code = stTriggerTaskCalcRequestParamCount(pContext->pCalcReq, &requestCount);
      QUERY_CHECK_CODE(code, lino, _end);
      if (requestCount == STREAM_CALC_REQ_MAX_WIN_NUM || !completeRoute) {
        code = stRealtimeContextFlushCalcRequest(pContext);
        QUERY_CHECK_CODE(code, lino, _end);
      }
      if (((pTask->placeHolderBitmap & PLACE_HOLDER_PARTITION_ROWS) ||
           (pTask->isVirtualTable && stRealtimeContextHasExtProgress(pContext))) &&
          !IS_TRIGGER_GROUP_TO_CHECK(pGroup)) {
        ST_TASK_DLOG("clear realtime WAL metas after calc dispatch, gid:%" PRId64
                     ", virtualMixedExt:%d, placeHolderBitmap:0x%" PRIx64,
                     pGroup->gid, pTask->isVirtualTable && stRealtimeContextHasExtProgress(pContext),
                     pTask->placeHolderBitmap);
        stRealtimeGroupClearMetadatas(pGroup);
      }
      stRealtimeGroupClearTempState(pGroup);
      code = stTriggerTaskReadyRecalcRequest(pTask, pGroup);
      QUERY_CHECK_CODE(code, lino, _end);
    } else {
      switch (pContext->status) {
        case STRIGGER_CONTEXT_FETCH_META: {
          pContext->status = STRIGGER_CONTEXT_ACQUIRE_REQUEST;
        }
        case STRIGGER_CONTEXT_ACQUIRE_REQUEST: {
          // MAX_DELAY triggers calculation independently of calcEventType.
          if (pContext->pCalcReq == NULL) {
            code = stTriggerTaskAcquireRequest(pTask, pContext->sessionId, pGroup->gid, &pContext->pCalcReq);
            QUERY_CHECK_CODE(code, lino, _end);
            if (pContext->pCalcReq == NULL) {
              if (pTask->lowLatencyCalc || pContext->calcParamPool.size >= tsStreamTriggerMaxPendingParams) {
                ST_TASK_DLOG("pause due to no available runner for group %" PRId64, pGroup->gid);
                goto _end;
              } else {
                ST_TASK_DLOG("skip calc due to no available runner for group %" PRId64, pGroup->gid);
                pContext->pMinGroup = NULL;
                continue;
              }
            }
          } else if (pTask->multiGroupBatch && TARRAY_SIZE(pContext->pCalcReq->params) == 0) {
            code = stTriggerTaskCheckCreate(pTask, pContext->pCalcReq, pContext->sessionId, pGroup->gid);
            QUERY_CHECK_CODE(code, lino, _end);
          }
          pContext->status = STRIGGER_CONTEXT_CHECK_CONDITION;
        }
        case STRIGGER_CONTEXT_CHECK_CONDITION: {
          code = stRealtimeGroupRetrievePendingCalc(pGroup);
          QUERY_CHECK_CODE(code, lino, _end);
          pContext->status = STRIGGER_CONTEXT_SEND_CALC_REQ;
        }
        case STRIGGER_CONTEXT_SEND_CALC_REQ: {
          if (pContext->pCalcReq == NULL) {
            // do nothing
          } else if (TARRAY_SIZE(pContext->pCalcReq->params) > 0) {
            code = stRealtimeContextSendCalcReq(pContext, false);
            QUERY_CHECK_CODE(code, lino, _end);
            if (pContext->pCalcReq != NULL && TARRAY_SIZE(pContext->pCalcReq->params) > 0) {
              // calc req has not been set
              goto _end;
            }
            if (pTask->placeHolderBitmap & PLACE_HOLDER_PARTITION_ROWS && !IS_TRIGGER_GROUP_TO_CHECK(pGroup)) {
              stRealtimeGroupClearMetadatas(pGroup);
            }
            stRealtimeGroupClearTempState(pGroup);
            code = stTriggerTaskReadyRecalcRequest(pTask, pGroup);
            QUERY_CHECK_CODE(code, lino, _end);
          } else if (!pTask->multiGroupBatch) {
            code = stTriggerTaskReleaseRequest(pTask, &pContext->pCalcReq, false);
            QUERY_CHECK_CODE(code, lino, _end);
          }
          break;
        }
        default: {
          ST_TASK_ELOG("invalid context status %d at %s:%d", pContext->status, __func__, __LINE__);
          code = TSDB_CODE_INVALID_PARA;
          QUERY_CHECK_CODE(code, lino, _end);
        }
      }
    }
    heapRemove(pContext->pMaxDelayHeap, &pGroup->heapNode);
    if (pGroup->nextExecTime != 0) {
      heapInsert(pContext->pMaxDelayHeap, &pGroup->heapNode);
    }
    pContext->status = pTask->multiGroupBatch ? STRIGGER_CONTEXT_FETCH_META : STRIGGER_CONTEXT_ACQUIRE_REQUEST;
    if (pContext->pMaxDelayHeap->min != NULL) {
      pContext->pMinGroup = container_of(pContext->pMaxDelayHeap->min, SSTriggerRealtimeGroup, heapNode);
      if (pContext->pMinGroup->nextExecTime > dispatchThrough &&
          !(pTask->lowLatencyCalc && (pContext->pMinGroup->pPendingCalcParams.neles > 0 ||
                                      pContext->pMinGroup->pPendingParWinCalcParams.neles > 0)) &&
          pContext->pMinGroup->pPendingCalcParams.neles < STREAM_CALC_REQ_MAX_WIN_NUM &&
          pContext->pMinGroup->pPendingParWinCalcParams.neles < STREAM_CALC_REQ_MAX_WIN_NUM &&
          pContext->calcParamPool.size < tsStreamTriggerMaxPendingParams) {
        if ((pContext->pMinGroup->pPendingCalcParams.neles > 0 ||
             pContext->pMinGroup->pPendingParWinCalcParams.neles > 0) &&
            !(hasWalProgress && pTask->idleTimeoutMs > 0) &&
            (!hasWalProgress || pContext->catchUp || stTriggerTaskNeedGroupColVals(pTask, true))) {
          int64_t resumeTime = pContext->pMinGroup->nextExecTime;
          ST_TASK_DLOG("defer next realtime calc until nextExecTime, gid:%" PRId64 ", resumeTime:%" PRId64
                       ", pendingParams:%" PRId64 ", pendingParWinParams:%" PRId64,
                       pContext->pMinGroup->gid, resumeTime, pContext->pMinGroup->pPendingCalcParams.neles,
                       pContext->pMinGroup->pPendingParWinCalcParams.neles);
          pContext->pMinGroup = NULL;
          code = stTriggerTaskAddWaitSession(pTask, pContext->sessionId, resumeTime);
          QUERY_CHECK_CODE(code, lino, _end);
          goto _end;
        }
        pContext->pMinGroup = NULL;
      }
    } else {
      pContext->pMinGroup = NULL;
    }
  }
  if (pTask->multiGroupBatch && pContext->pCalcReq != NULL) {
    int32_t requestCount = 0;
    code = stTriggerTaskCalcRequestParamCount(pContext->pCalcReq, &requestCount);
    QUERY_CHECK_CODE(code, lino, _end);
    code = requestCount > 0 ? stRealtimeContextFlushCalcRequest(pContext)
                            : stTriggerTaskReleaseRequest(pTask, &pContext->pCalcReq, false);
    QUERY_CHECK_CODE(code, lino, _end);
    pContext->status = STRIGGER_CONTEXT_FETCH_META;
  }

_calc_done:
  if (pContext->walCheckpointMaxDelayCutoff) {
    HeapNode *min = pContext->pMaxDelayHeap->min;
    if (min &&
        container_of(min, SSTriggerRealtimeGroup, heapNode)->nextExecTime <= pContext->walCheckpointMaxDelayCutoff) {
      // A batch can flush before the remaining group gets a slot.
      pContext->status = STRIGGER_CONTEXT_ACQUIRE_REQUEST;
      goto _end;
    }
    pContext->walCheckpointMaxDelayCutoff = 0;
    stCancelWalCheckpointWake(pTask);
  }
  if (nested && stUsesTimeAlignRows(pTask) && !pContext->suppressOutput) {
    TAOS_CHECK_RETURN(stAcceptAlignedChain(pContext));
  }
  if (waitingGroups) {
    pContext->status = STRIGGER_CONTEXT_FETCH_META;
    goto _end;
  }
  // Drain the nested backlog before starting another input round, even after all groups were checked.
  if (TD_DLIST_NELES(&pContext->groupsToCheck) > 0 ||
      (nested && !pContext->suppressOutput && pContext->nestedPendingParamCount >= tsStreamTriggerMaxPendingParams)) {
    pContext->status = STRIGGER_CONTEXT_CHECK_CONDITION;
    goto _check;
  }

  stRealtimeContextReclaimStaleExtDataBlocks(pContext);
  // Notify-only streams have no output tables to delete.
  if (taosArrayGetSize(pTask->runnerList) == 0) {
    taosArrayClear(pContext->groupsToDelete);
  }
  int32_t deleteGroupNum = taosArrayGetSize(pContext->groupsToDelete);
  if (deleteGroupNum > 0) {
    pContext->status = STRIGGER_CONTEXT_SEND_DROP_REQ;
    bool allSent = true;
    for (int32_t i = deleteGroupNum - 1; i >= 0; i--) {
      int64_t               gid = ((int64_t *)TARRAY_DATA(pContext->groupsToDelete))[i];
      bool                  drop = true;
      SSTriggerDropRequest *pDropReq = NULL;
      code = stTriggerTaskAcquireDropTableRequest(pTask, pContext->sessionId, gid, &pDropReq);
      QUERY_CHECK_CODE(code, lino, _end);
      if (pDropReq) {
        pContext->dropReqIndex = i;
        bool needColVal = false;
        code = stRealtimeContextSendDropTableReq(pContext, gid, pDropReq, &needColVal);
        QUERY_CHECK_CODE(code, lino, _end);
        if (needColVal) {
          allSent = false;
        } else {
          code = stTriggerTaskReleaseDropTableRequest(pTask, &pDropReq);
          QUERY_CHECK_CODE(code, lino, _end);
        }
        taosArrayRemove(pContext->groupsToDelete, i);
      }
    }
    if (!allSent) {
      goto _end;
    }
  }

  bool noPendingCalc = true;
  if (nested) {
    noPendingCalc = pContext->nestedPendingParamCount == 0;
  } else {
    noPendingCalc = pContext->calcParamPool.size == 0;
  }

  bool forwardDoneVer = false;
  if (noPendingCalc && !pContext->drainingWalCheckpoint) {
    int64_t nRunningReq = 0;
    code = stTriggerTaskGetRunningReq(pTask, pContext->sessionId, &nRunningReq);
    QUERY_CHECK_CODE(code, lino, _end);
    forwardDoneVer = (nRunningReq == 0);
  }
  if (forwardDoneVer && atomic_load_32(&pTask->alignedCheckpointHold) && !stHasReadyAlignedRepair(pTask, 0) &&
      TD_DLIST_NELES(&pContext->groupsToCheck) == 0) {
    int32_t                      i = 0;
    SSTriggerGroupPendingRecalc *pending = NULL;
    while ((pending = tSimpleHashIterate(pTask->pGroupPendingRecalcs, pending, &i))) {
      if (TD_DLIST_HEAD(&pending->pendingRequests)) break;
    }
    if (!pending) atomic_store_32(&pTask->alignedCheckpointHold, 0);
  }
  pContext->recovering = false;
  // For STREAM_TRIGGER_EVENT, pre-compute the set of vgIds that currently have at
  // least one group with an active start/end streak. This replaces an O(G) scan
  // per progress entry (total O(G x V)) with a single O(G) build + O(1) lookup
  // per progress entry (total O(G + V)).
  // Stage the cursor only after the groups on this ordinary page have consumed their input.
  bool stageAlignedDone = !forwardDoneVer && noPendingCalc && nested && pContext->timeAlignRound &&
                          !pContext->suppressOutput && !pContext->timeAlignRestart && !pContext->metaPool.size &&
                          !stRealtimeContextHasPendingWalPulls(pContext);
  SHashObj *pFrozenVgIds = NULL;
  if ((forwardDoneVer || stageAlignedDone) && pTask->triggerType == STREAM_TRIGGER_EVENT &&
      pTask->pRealtimeContext != NULL && pTask->pRealtimeContext->pGroups != NULL) {
    pFrozenVgIds = taosHashInit(8, taosGetDefaultHashFunction(TSDB_DATA_TYPE_INT), false, HASH_NO_LOCK);
    if (pFrozenVgIds != NULL) {
      int32_t                  giter = 0;
      SSTriggerRealtimeGroup **ppGroup = tSimpleHashIterate(pTask->pRealtimeContext->pGroups, NULL, &giter);
      while (ppGroup != NULL) {
        SSTriggerRealtimeGroup *pGroup = *ppGroup;
        if (pGroup != NULL && (pGroup->startCondCount > 0 || pGroup->endCondCount > 0 ||
                               stEventTreeHasActiveLeafStreak(pGroup->leafStreaks) ||
                               stEventTreeHasOpenNodeWindow(pGroup->openNodeWindows))) {
          int32_t vgId = pGroup->vgId;
          if (taosHashPut(pFrozenVgIds, &vgId, sizeof(int32_t), &vgId, sizeof(int32_t)) != 0) {
            taosHashCleanup(pFrozenVgIds);
            pFrozenVgIds = NULL;
            break;
          }
        }
        ppGroup = tSimpleHashIterate(pTask->pRealtimeContext->pGroups, ppGroup, &giter);
      }
    }
  }
  bool                  walBehind = false;
  int32_t               iter = 0;
  SSTriggerWalProgress *pProgress = tSimpleHashIterate(pContext->pReaderWalProgress, NULL, &iter);
  while (pProgress != NULL) {
    if (forwardDoneVer || stageAlignedDone) {
      int64_t newDoneVer = pProgress->lastScanVer;
      if (pTask->triggerType == STREAM_TRIGGER_EVENT) {
        // Freeze doneVer if any group on this vnode has an active streak so that WAL replay
        // from doneVer+1 naturally rebuilds the streak state on restart.
        int32_t vgId = *(int32_t *)tSimpleHashGetKey(pProgress, NULL);
        if (pFrozenVgIds != NULL && taosHashGet(pFrozenVgIds, &vgId, sizeof(int32_t)) != NULL) {
          newDoneVer = pProgress->doneVer;  // freeze at current position
        }
      }
      if (forwardDoneVer) {
        pProgress->doneVer = newDoneVer;
        pProgress->alignedDrainedVer = 0;
      } else if (pTask->triggerType != STREAM_TRIGGER_EVENT || pFrozenVgIds != NULL) {
        pProgress->alignedDrainedVer = newDoneVer;
      }
    }
    if (pProgress->lastScanVer < pProgress->savedVer) {
      pContext->recovering = true;
    }
    walBehind |= pProgress->lastScanVer > TMAX(pProgress->doneVer, pProgress->savedVer);
    stTriggerTaskUpdateReaderProgress(pTask, pProgress);
    pProgress = tSimpleHashIterate(pContext->pReaderWalProgress, pProgress, &iter);
  }
  if (pFrozenVgIds != NULL) {
    taosHashCleanup(pFrozenVgIds);
    pFrozenVgIds = NULL;
  }

  if (stTriggerTaskCanDrainWalCheckpoint(pTask)) {
    // On this path doneVer advances for all readers together. Only age an actual outstanding cut.
    if (!walBehind || pContext->recovering) {
      pContext->walStallDeadlineUs = 0;
    } else if (!pContext->walStallDeadlineUs) {
      pContext->walStallDeadlineUs = checkStartMonoUs + STRIGGER_WAL_STALL_INTERVAL_US;
    } else if (!pContext->drainingWalCheckpoint && checkStartMonoUs >= pContext->walStallDeadlineUs &&
               !stRealtimeContextHasPendingWalPulls(pContext)) {
      code = stRealtimeContextBeginWalDrain(pContext, now);
      QUERY_CHECK_CODE(code, lino, _end);
    }
  }

  if (pContext->drainingWalCheckpoint) {
    pContext->status = STRIGGER_CONTEXT_FETCH_META;
  } else if (!periodicCheckpointChecked) {
    stTriggerTaskGeneratePeriodicCheckpoint(pTask, pContext, now);
  }

  code = stRealtimeContextAddUserRecalc(pContext);
  QUERY_CHECK_CODE(code, lino, _end);
  if (pContext->drainingWalCheckpoint) goto _end;

  if (pContext->timeAlignRound && forwardDoneVer && !pContext->metaPool.size && !hasReadyDeferredGroup &&
      !stRealtimeContextHasPendingWalPulls(pContext)) {
    int64_t outstanding = 0;
    code = stTriggerTaskGetRunningReq(pTask, pContext->sessionId, &outstanding);
    QUERY_CHECK_CODE(code, lino, _end);
    if (outstanding) goto _end;
    code = stDropTimeAlignBoundary(pContext, true);
    QUERY_CHECK_CODE(code, lino, _end);
    goto _end;
  }

  if (pContext->pPeriod != NULL) {
    pContext->pPeriod->dispatchDone = noPendingCalc;
    pContext->status = STRIGGER_CONTEXT_IDLE;
    code = stTriggerTaskAddWaitSessionForReason(pTask, pContext->sessionId, now + STREAM_TRIGGER_IDLE_TIME_NS,
                                                STREAM_TRIGGER_WAIT_PERIOD_POLL);
    QUERY_CHECK_CODE(code, lino, _end);
  } else if (pTask->triggerType == STREAM_TRIGGER_PERIOD) {
    stTriggerTaskNextTimeWindow(pTask, &pContext->periodWindow);
    pContext->status = STRIGGER_CONTEXT_IDLE;
    code = stTriggerTaskAddWaitSession(pTask, pContext->sessionId, pContext->periodWindow.ekey);
    QUERY_CHECK_CODE(code, lino, _end);
  } else {
    // todo(kjq): start history calc if needed
    if (pContext->catchUp && !hasReadyDeferredGroup && !stRealtimeContextHasPendingWalPulls(pContext)) {
      // add the task to wait list since it catches up all readers
      pContext->status = STRIGGER_CONTEXT_IDLE;
      int64_t resumeTime = (nested ? now : taosGetTimestampNs()) + STREAM_TRIGGER_IDLE_TIME_NS;
      code = stTriggerTaskAddWaitSession(pTask, pContext->sessionId, resumeTime);
      QUERY_CHECK_CODE(code, lino, _end);
    } else {
      // pull new wal metas
      pContext->status = STRIGGER_CONTEXT_FETCH_META;
      hasWalProgress = stRealtimeContextHasWalProgress(pContext);
      hasExtProgress = stRealtimeContextHasExtProgress(pContext);
      if (hasExtProgress && !hasWalProgress) {
        /* EXT-only stream: after calc round, restart EXT polling via stRealtimeContextCheckExt.
         * pReaderWalProgress is always empty for EXT-only streams - never fall through to WAL pull. */
        ST_TASK_DLOG("ext: post-calc, restarting EXT poll via stRealtimeContextCheckExt %s", "");
        code = stRealtimeContextCheckExt(pContext, now);
        QUERY_CHECK_CODE(code, lino, _end);
        goto _end;
      }
      if (hasWalProgress) {
        if (stRealtimeContextHasPendingWalPulls(pContext)) {
          ST_TASK_DLOG("wal: skip duplicate post-calc pull while an in-flight WAL pull exists, status:%d",
                       pContext->status);
        } else {
          for (pContext->curReaderIdx = 0; pContext->curReaderIdx < TARRAY_SIZE(pTask->readerList);
               pContext->curReaderIdx++) {
            code = stRealtimeContextSendPullReq(pContext, (pContext->walMode == STRIGGER_WAL_META_WITH_DATA)
                                                              ? STRIGGER_PULL_WAL_META_DATA_NEW
                                                              : STRIGGER_PULL_WAL_META_NEW);
            QUERY_CHECK_CODE(code, lino, _end);
          }
        }
      }
      if (hasExtProgress) {
        ST_TASK_DLOG("ext: mixed post-calc, restarting external polling %s", "");
        code = stRealtimeContextCheckExt(pContext, now);
        QUERY_CHECK_CODE(code, lino, _end);
      }
    }
  }

_end:
  if (code == TSDB_CODE_SUCCESS && pContext == pTask->pRealtimeContext && pContext->drainingWalCheckpoint) {
    code = stRealtimeContextCaptureWalCheckpoint(pContext);
    if (code == TSDB_CODE_SUCCESS) {
      HeapNode *min = pContext->pMaxDelayHeap->min;
      bool      needRetry = !pContext->pWalCheckpointWaits || !stRealtimeContextWalCalcIsWaiting(pContext);
      if (min || needRetry) {
        int64_t windowDeadline = min ? container_of(min, SSTriggerRealtimeGroup, heapNode)->nextExecTime : 0;
        // An already due window may still need a slot. Retry it on the monotonic backoff.
        if (windowDeadline <= taosGetTimestampNs()) windowDeadline = 0;
        int64_t retryAt =
            needRetry || !windowDeadline ? taosGetMonoTimestampNs() + STREAM_TRIGGER_IDLE_TIME_NS : INT64_MAX;
        code = stTriggerTaskAddWait(pTask, pContext->sessionId, retryAt, STREAM_TRIGGER_WAIT_WAL_CHECKPOINT,
                                    windowDeadline);
      }
    }
  } else if (code == TSDB_CODE_SUCCESS && pContext == pTask->pRealtimeContext &&
             pContext->walCheckpointMaxDelayCutoff && pContext->status == STRIGGER_CONTEXT_ACQUIRE_REQUEST) {
    // An ACK for a slot held by another session only wakes that session.
    code = stTriggerTaskAddWaitSessionForReason(pTask, pContext->sessionId,
                                                taosGetMonoTimestampNs() + STREAM_TRIGGER_IDLE_TIME_NS,
                                                STREAM_TRIGGER_WAIT_WAL_CHECKPOINT);
  }
  if (pTask->checkpointSyncRetryMonoUs && checkStartMonoUs >= pTask->checkpointSyncRetryMonoUs &&
      pContext == pTask->pRealtimeContext) {
    TAOS_UNUSED(stTriggerTaskSyncCommittedCheckpoint(pTask, NULL, 0, true));
  }
  if (code != TSDB_CODE_SUCCESS && pContext->pCalcReq != NULL) {
    // Releasing this request discards its dequeued windows. Another ACK must not confirm their WAL cursor.
    int32_t requestCount = 0;
    if (pContext == pTask->pRealtimeContext && stTriggerTaskCanDrainWalCheckpoint(pTask) &&
        (stTriggerTaskCalcRequestParamCount(pContext->pCalcReq, &requestCount) != TSDB_CODE_SUCCESS ||
         requestCount > 0)) {
      pContext->walStallError = code;
    }
    stDestroyRealtimeNestedCalcMaterialization(&pContext->pNestedCalcMaterialization);
    TAOS_UNUSED(stTriggerTaskReleaseRequest(pTask, &pContext->pCalcReq, false));
  }
  checkEndMonoUs = streamTaskGetMonotonicUs();
  stTaskStatsRecordTriggerCheck(pTask->pStats, false,
                                checkEndMonoUs >= checkStartMonoUs ? (uint64_t)(checkEndMonoUs - checkStartMonoUs) : 0,
                                checkEndMonoUs, taosGetTimestampMs());
  if (code != TSDB_CODE_SUCCESS) {
    stTaskStatsRecordTriggerEvent(pTask->pStats, STREAM_TRIGGER_EVENT_FAILURE, 1, checkEndMonoUs);
    ST_TASK_ELOG("%s failed at line %d since %s", __func__, lino, tstrerror(code));
  }
  return code;
}

static int32_t stRealtimeContextProcWalMeta(SSTriggerRealtimeContext *pContext, SSTriggerWalProgress *pProgress,
                                            int64_t nowNs) {
  int32_t             code = TSDB_CODE_SUCCESS;
  int32_t             lino = 0;
  SStreamTriggerTask *pTask = pContext->pTask;

  bool scannedFromZero = pProgress->startVer == 0 && pProgress->lastScanVer == 0;
  pProgress->lastScanVer = pContext->pMetaBlock->info.version;
  bool needShrink = pContext->recovering && (pProgress->lastScanVer > pProgress->savedVer);
  if (needShrink) {
    pProgress->lastScanVer = pProgress->savedVer;
  }
  int32_t vgId = pProgress->pTaskAddr->nodeId;

  // add wal meta in groups
  int32_t nrows = blockDataGetNumOfRows(pContext->pMetaBlock);
  if (needShrink && nrows > 0) {
    SColumnInfoData *pVerCol = taosArrayGet(pContext->pMetaBlock->pDataBlock, STREAM_WAL_META_VER_COL);
    QUERY_CHECK_NULL(pVerCol, code, lino, _end, terrno);
    int64_t *pVers = (int64_t *)pVerCol->pData;
    while (nrows > 0 && pVers[nrows - 1] >= pProgress->savedVer) {
      nrows--;
    }
  }
  if (nrows > 0) {
    SColumnInfoData *pGidCol = taosArrayGet(pContext->pMetaBlock->pDataBlock, STREAM_WAL_META_GID_COL);
    QUERY_CHECK_NULL(pGidCol, code, lino, _end, terrno);
    int64_t         *pGids = (int64_t *)pGidCol->pData;
    SColumnInfoData *pSkeyCol = taosArrayGet(pContext->pMetaBlock->pDataBlock, STREAM_WAL_META_SKEY_COL);
    QUERY_CHECK_NULL(pSkeyCol, code, lino, _end, terrno);
    int64_t         *pSkeys = (int64_t *)pSkeyCol->pData;
    SColumnInfoData *pEkeyCol = taosArrayGet(pContext->pMetaBlock->pDataBlock, STREAM_WAL_META_EKEY_COL);
    QUERY_CHECK_NULL(pEkeyCol, code, lino, _end, terrno);
    int64_t         *pEkeys = (int64_t *)pEkeyCol->pData;
    SColumnInfoData *pVerCol = taosArrayGet(pContext->pMetaBlock->pDataBlock, STREAM_WAL_META_VER_COL);
    QUERY_CHECK_NULL(pVerCol, code, lino, _end, terrno);
    int64_t *pVers = (int64_t *)pVerCol->pData;
    int32_t *pRollupTbCounts = NULL;
    if (blockDataGetNumOfCols(pContext->pMetaBlock) > STREAM_WAL_META_ROLLUP_TBCOUNT_COL) {
      SColumnInfoData *pRollupTbCountCol =
          taosArrayGet(pContext->pMetaBlock->pDataBlock, STREAM_WAL_META_ROLLUP_TBCOUNT_COL);
      QUERY_CHECK_NULL(pRollupTbCountCol, code, lino, _end, terrno);
      pRollupTbCounts = (int32_t *)pRollupTbCountCol->pData;
    }
    if (pTask->isVirtualTable) {
      for (int32_t i = 0; i < nrows; i++) {
        int64_t                 otbUid = pGids[i];
        SSTriggerOrigTableInfo *pOrigTableInfo = tSimpleHashGet(pTask->pOrigTableInfos, &otbUid, sizeof(int64_t));
        if (pOrigTableInfo == NULL) {
          bool matchedNestedGroup = false;
          if (BIT_FLAG_TEST_MASK(pTask->addOptions, STREAM_OPTION_NESTED_WINDOW_PLAN) || pTask->multiGroupBatch) {
            int32_t                 iter = 0;
            SSTriggerVirtTableInfo *pVirtTableInfo = tSimpleHashIterate(pTask->pVirtTableInfos, NULL, &iter);
            while (pVirtTableInfo != NULL) {
              if (pVirtTableInfo->vgId == vgId && stTriggerTaskMatchVirtTableInfo(pVirtTableInfo, otbUid)) {
                SSTriggerRealtimeGroup *pGroup = NULL;
                code = stRealtimeContextGetOrCreateGroup(pContext, otbUid, pVirtTableInfo->vgId, &pGroup);
                QUERY_CHECK_CODE(code, lino, _end);
                SSTriggerMetaData meta = {.skey = pSkeys[i], .ekey = pEkeys[i], .ver = pVers[i]};
                SSTriggerReaderDataKey readerKey =
                    stTriggerTaskInternalReaderDataKey(0, pVirtTableInfo->tbUid, pVirtTableInfo->vgId);
                code = stRealtimeGroupAddMeta(pGroup, vgId, &readerKey, &meta, nowNs, 0);
                QUERY_CHECK_CODE(code, lino, _end);
                if ((pContext->pPeriod == NULL || pContext->pPeriod->pReceiving == NULL) &&
                    stRealtimeGroupNeedCheck(pGroup) && !IS_TRIGGER_GROUP_TO_CHECK(pGroup)) {
                  TD_DLIST_APPEND(&pContext->groupsToCheck, pGroup);
                }
                matchedNestedGroup = true;
                break;
              }
              pVirtTableInfo = tSimpleHashIterate(pTask->pVirtTableInfos, pVirtTableInfo, &iter);
            }
          }
          if (!matchedNestedGroup) {
            ST_TASK_DLOG("skip wal meta for unmapped orig table %" PRId64 " during virtual table patch", otbUid);
          }
          continue;
        }
        for (int32_t j = 0; j < TARRAY_SIZE(pOrigTableInfo->pVtbUids); j++) {
          int64_t                 vtbUid = *(int64_t *)TARRAY_GET_ELEM(pOrigTableInfo->pVtbUids, j);
          SSTriggerVirtTableInfo *pVirtTableInfo = tSimpleHashGet(pTask->pVirtTableInfos, &vtbUid, sizeof(int64_t));
          if (pVirtTableInfo == NULL) {
            ST_TASK_DLOG("skip wal meta for retired virtual table %" PRId64, vtbUid);
            continue;
          }
          for (int32_t k = 0; k < TARRAY_SIZE(pVirtTableInfo->tbGids); k++) {
            int64_t                 gid = *(int64_t *)TARRAY_GET_ELEM(pVirtTableInfo->tbGids, k);
            SSTriggerRealtimeGroup *pGroup = NULL;
            code = stRealtimeContextGetOrCreateGroup(pContext, gid, pVirtTableInfo->vgId, &pGroup);
            QUERY_CHECK_CODE(code, lino, _end);
            SSTriggerMetaData meta = {.skey = pSkeys[i], .ekey = pEkeys[i], .ver = pVers[i]};
            SSTriggerReaderDataKey readerKey =
                stTriggerTaskInternalReaderDataKey(pOrigTableInfo->tbSuid, pOrigTableInfo->tbUid, vgId);
            code = stRealtimeGroupAddMeta(pGroup, vgId, &readerKey, &meta, nowNs, vtbUid);
            QUERY_CHECK_CODE(code, lino, _end);
            if ((pContext->pPeriod == NULL || pContext->pPeriod->pReceiving == NULL) &&
                stRealtimeGroupNeedCheck(pGroup) && !IS_TRIGGER_GROUP_TO_CHECK(pGroup)) {
              TD_DLIST_APPEND(&pContext->groupsToCheck, pGroup);
            }
          }
        }
      }
    } else {
      for (int32_t i = 0; i < nrows; i++) {
        int64_t gid = pGids[i];
        if (pTask->isRollup && pRollupTbCounts != NULL) {
          code = stTriggerTaskUpdateRollupTbCount(pContext->pRollupTbCount, pContext->pRollupTbCountSeen, vgId, gid,
                                                  pRollupTbCounts[i]);
          QUERY_CHECK_CODE(code, lino, _end);
        }
        void                   *px = tSimpleHashGet(pContext->pGroups, &gid, sizeof(int64_t));
        SSTriggerRealtimeGroup *pGroup = NULL;
        if (px == NULL) {
          pGroup = taosMemoryCalloc(1, sizeof(SSTriggerRealtimeGroup));
          QUERY_CHECK_NULL(pGroup, code, lino, _end, terrno);
          code = tSimpleHashPut(pContext->pGroups, &gid, sizeof(int64_t), &pGroup, POINTER_BYTES);
          if (code != TSDB_CODE_SUCCESS) {
            taosMemoryFreeClear(pGroup);
            QUERY_CHECK_CODE(code, lino, _end);
          }
          code = stRealtimeGroupInit(pGroup, pContext, gid, vgId);
          if (code != TSDB_CODE_SUCCESS) {
            tSimpleHashRemove(pContext->pGroups, &gid, sizeof(int64_t));
            QUERY_CHECK_CODE(code, lino, _end);
          }
        } else {
          pGroup = *(SSTriggerRealtimeGroup **)px;
        }
        SSTriggerMetaData meta = {.skey = pSkeys[i], .ekey = pEkeys[i], .ver = pVers[i]};
        code = stRealtimeGroupAddMeta(pGroup, vgId, NULL, &meta, nowNs, 0);
        QUERY_CHECK_CODE(code, lino, _end);
        if ((pContext->pPeriod == NULL || pContext->pPeriod->pReceiving == NULL) && stRealtimeGroupNeedCheck(pGroup) &&
            !IS_TRIGGER_GROUP_TO_CHECK(pGroup)) {
          TD_DLIST_APPEND(&pContext->groupsToCheck, pGroup);
        }
      }
    }
  }

  // process delete data
  nrows = blockDataGetNumOfRows(pContext->pDeleteBlock);
  if (needShrink && nrows > 0) {
    SColumnInfoData *pVerCol = taosArrayGet(pContext->pDeleteBlock->pDataBlock, STREAM_WAL_META_VER_COL);
    QUERY_CHECK_NULL(pVerCol, code, lino, _end, terrno);
    int64_t *pVers = (int64_t *)pVerCol->pData;
    while (nrows > 0 && pVers[nrows - 1] >= pProgress->savedVer) {
      nrows--;
    }
  }
  if (nrows > 0) {
    ST_TASK_DLOG("got %d rows of delete data", nrows);
    SColumnInfoData *pGidCol = taosArrayGet(pContext->pDeleteBlock->pDataBlock, STREAM_WAL_META_GID_COL);
    QUERY_CHECK_NULL(pGidCol, code, lino, _end, terrno);
    int64_t         *pGids = (int64_t *)pGidCol->pData;
    SColumnInfoData *pSkeyCol = taosArrayGet(pContext->pDeleteBlock->pDataBlock, STREAM_WAL_META_SKEY_COL);
    QUERY_CHECK_NULL(pSkeyCol, code, lino, _end, terrno);
    int64_t         *pSkeys = (int64_t *)pSkeyCol->pData;
    SColumnInfoData *pEkeyCol = taosArrayGet(pContext->pDeleteBlock->pDataBlock, STREAM_WAL_META_EKEY_COL);
    QUERY_CHECK_NULL(pEkeyCol, code, lino, _end, terrno);
    int64_t         *pEkeys = (int64_t *)pEkeyCol->pData;
    SColumnInfoData *pVerCol = taosArrayGet(pContext->pDeleteBlock->pDataBlock, STREAM_WAL_META_VER_COL);
    QUERY_CHECK_NULL(pVerCol, code, lino, _end, terrno);
    int64_t *pVers = (int64_t *)pVerCol->pData;
    if (pTask->isVirtualTable) {
      for (int32_t i = 0; i < nrows; i++) {
        int64_t                 otbUid = pGids[i];
        SSTriggerOrigTableInfo *pOrigTableInfo = tSimpleHashGet(pTask->pOrigTableInfos, &otbUid, sizeof(int64_t));
        if (pOrigTableInfo == NULL) {
          ST_TASK_DLOG("skip delete meta for unmapped orig table %" PRId64 " during virtual table patch", otbUid);
          continue;
        }
        for (int32_t j = 0; j < TARRAY_SIZE(pOrigTableInfo->pVtbUids); j++) {
          int64_t                 vtbUid = *(int64_t *)TARRAY_GET_ELEM(pOrigTableInfo->pVtbUids, j);
          SSTriggerVirtTableInfo *pVirtTableInfo = tSimpleHashGet(pTask->pVirtTableInfos, &vtbUid, sizeof(int64_t));
          if (pVirtTableInfo == NULL) {
            ST_TASK_DLOG("skip delete meta for retired virtual table %" PRId64, vtbUid);
            continue;
          }
          for (int32_t k = 0; k < TARRAY_SIZE(pVirtTableInfo->tbGids); k++) {
            int64_t                 gid = *(int64_t *)TARRAY_GET_ELEM(pVirtTableInfo->tbGids, k);
            SSTriggerRealtimeGroup *pGroup = NULL;
            code = stRealtimeContextGetOrCreateGroup(pContext, gid, pVirtTableInfo->vgId, &pGroup);
            QUERY_CHECK_CODE(code, lino, _end);
            STimeWindow range = {.skey = pSkeys[i], .ekey = pEkeys[i]};
            ST_TASK_DLOG("add recalc request for delete data, gid: %" PRId64 ", start: %" PRId64 ", end: %" PRId64, gid,
                         range.skey, range.ekey);
            code = stInvalidateTimeAlignChange(pContext, gid, vtbUid, pProgress->pTaskAddr->taskId, otbUid, range, -1,
                                               NULL);
            QUERY_CHECK_CODE(code, lino, _end);
            code = stTriggerTaskAddSourceRecalcRequest(pTask, pGroup, &range, false, otbUid);
            QUERY_CHECK_CODE(code, lino, _end);
            if ((pContext->pPeriod == NULL || pContext->pPeriod->pReceiving == NULL) &&
                stRealtimeGroupNeedCheck(pGroup) && !IS_TRIGGER_GROUP_TO_CHECK(pGroup)) {
              TD_DLIST_APPEND(&pContext->groupsToCheck, pGroup);
            }
          }
        }
      }
    } else {
      for (int32_t i = 0; i < nrows; i++) {
        int64_t                 gid = pGids[i];
        void                   *px = tSimpleHashGet(pContext->pGroups, &gid, sizeof(int64_t));
        SSTriggerRealtimeGroup *pGroup = NULL;
        if (px == NULL) {
          pGroup = taosMemoryCalloc(1, sizeof(SSTriggerRealtimeGroup));
          QUERY_CHECK_NULL(pGroup, code, lino, _end, terrno);
          code = tSimpleHashPut(pContext->pGroups, &gid, sizeof(int64_t), &pGroup, POINTER_BYTES);
          if (code != TSDB_CODE_SUCCESS) {
            taosMemoryFreeClear(pGroup);
            QUERY_CHECK_CODE(code, lino, _end);
          }
          code = stRealtimeGroupInit(pGroup, pContext, gid, vgId);
          QUERY_CHECK_CODE(code, lino, _end);
        } else {
          pGroup = *(SSTriggerRealtimeGroup **)px;
        }
        STimeWindow range = {.skey = pSkeys[i], .ekey = pEkeys[i]};
        ST_TASK_DLOG("add recalc request for delete data, gid: %" PRId64 ", start: %" PRId64 ", end: %" PRId64, gid,
                     range.skey, range.ekey);
        code = stTriggerTaskAddRecalcRequest(pTask, pGroup, &range, false, false, false, 0);
        QUERY_CHECK_CODE(code, lino, _end);
        if ((pContext->pPeriod == NULL || pContext->pPeriod->pReceiving == NULL) && stRealtimeGroupNeedCheck(pGroup) &&
            !IS_TRIGGER_GROUP_TO_CHECK(pGroup)) {
          TD_DLIST_APPEND(&pContext->groupsToCheck, pGroup);
        }
      }
    }
  }

  // process new dropped tables
  nrows = blockDataGetNumOfRows(pContext->pTableBlock);
  if (nrows > 0) {
    int32_t          iCol = 0;
    SColumnInfoData *pUidCol = taosArrayGet(pContext->pTableBlock->pDataBlock, iCol++);
    QUERY_CHECK_NULL(pUidCol, code, lino, _end, terrno);
    SColumnInfoData *pVerCol = taosArrayGet(pContext->pTableBlock->pDataBlock, iCol++);
    QUERY_CHECK_NULL(pVerCol, code, lino, _end, terrno);
    SColumnInfoData *pTypeCol = taosArrayGet(pContext->pTableBlock->pDataBlock, iCol++);
    QUERY_CHECK_NULL(pTypeCol, code, lino, _end, terrno);
    int64_t *pUids = (int64_t *)pUidCol->pData;
    int64_t *pVers = (int64_t *)pVerCol->pData;
    uint8_t *pTypes = (uint8_t *)pTypeCol->pData;
    // A WAL table-change row carries the version of the record that produced it, so it is compared
    // against the watermark of rows already applied instead of savedVer: the WAL window ends at
    // savedVer and replaying that window delivers the row recorded at savedVer once more, even
    // though it already became a patch item. A TABLE_BLOCK_ADD_RECHECK row is exempt from that
    // comparison: the reader-side cache recheck stamps it with the pull request cursor, which does
    // not move when the change comes from another vgroup, so two independent rechecks can carry the
    // same version and filter the later one out. Shadow replay bundles rebuild their own state from
    // an inclusive WAL window and keep the previous savedVer - 1 gate.
    const int64_t tbPatchWatermark = pContext->suppressOutput ? pProgress->savedVer - 1 : pProgress->savedTbVer;
#define TRIGGER_SUPPORT_RUNTIME_VTABLE_CHANGE 1
    for (int32_t i = 0; i < nrows; i++) {
      const bool isRecheckAdd = (pTypes[i] == TABLE_BLOCK_ADD_RECHECK);
      const bool passesTbGate = isRecheckAdd || pVers[i] > tbPatchWatermark;
      if (pTypes[i] == TABLE_BLOCK_REFRESH_WIDTH && pTask->flatVirtualScan && passesTbGate) {
        // The physical Reader owns the WAL cursor. Fetch the virtual table from its own vgroup.
        SSHashObj              *pending = pContext->patchContext.pPatchItems;
        SSTriggerVirtTableInfo *table = tSimpleHashGet(pTask->pVirtTableInfos, &pUids[i], sizeof(pUids[i]));
        if (table && !tSimpleHashGet(pending, &pUids[i], sizeof(pUids[i]))) {
          SSTriggerVTablePatchItem item = {
              .vtbUid = pUids[i], .ver = pVers[i], .vgId = table->vgId, .op = TABLE_BLOCK_ADD};
          code = tSimpleHashPut(pending, &pUids[i], sizeof(pUids[i]), &item, sizeof(item));
          QUERY_CHECK_CODE(code, lino, _end);
          ST_TASK_DLOG("refresh physical column width for virtual table:%" PRId64 ", reader vgId:%d, table vgId:%d",
                       pUids[i], vgId, table->vgId);
        }
        pProgress->savedTbVer = TMAX(pProgress->savedTbVer, pVers[i]);
        continue;
      }
      if ((pTypes[i] == TABLE_BLOCK_ADD || isRecheckAdd) && pTask->isVirtualTable && passesTbGate) {
#if TRIGGER_SUPPORT_RUNTIME_VTABLE_CHANGE
        ST_TASK_DLOG("found runtime virtual table %s, uid:%" PRId64 ", ver:%" PRId64,
                     isRecheckAdd ? "add (cache recheck)" : "add", pUids[i], pVers[i]);
        SSTriggerVTablePatchItem  newItem = {.vtbUid = pUids[i], .ver = pVers[i], .vgId = vgId, .op = TABLE_BLOCK_ADD};
        SSHashObj                *pPatchItems = pContext->patchContext.pPatchItems;
        // stRealtimeContextInitPatchContext() initializes pPatchItems for every virtual-table
        // context; enforce the invariant here instead of relying on it only in comments, so a
        // missing init fails loudly rather than silently dropping the runtime vtable change.
        QUERY_CHECK_NULL(pPatchItems, code, lino, _end, TSDB_CODE_STREAM_INTERNAL_ERROR);
        SSTriggerVTablePatchItem *pExist = tSimpleHashGet(pPatchItems, &pUids[i], sizeof(int64_t));
        if (pExist == NULL) {
          code = tSimpleHashPut(pPatchItems, &pUids[i], sizeof(int64_t), &newItem, sizeof(SSTriggerVTablePatchItem));
          QUERY_CHECK_CODE(code, lino, _end);
        } else {
          *pExist = newItem;
        }
        // Only a WAL record version advances the applied watermark; a recheck row reports the same
        // change at most once and must not hide a later change that reuses the cursor.
        if (!isRecheckAdd) {
          pProgress->savedTbVer = TMAX(pProgress->savedTbVer, pVers[i]);
        }
#else
        ST_TASK_DLOG("found new added/altered virtual table, uid:%" PRId64, pUids[i]);
        code = TSDB_CODE_INTERNAL_ERROR;
        QUERY_CHECK_CODE(code, lino, _end);
#endif
      } else if (pTypes[i] == TABLE_BLOCK_RETIRE && pTask->isVirtualTable && pVers[i] > tbPatchWatermark) {
#if TRIGGER_SUPPORT_RUNTIME_VTABLE_CHANGE
        ST_TASK_DLOG("found runtime virtual table retire, uid:%" PRId64 ", ver:%" PRId64, pUids[i], pVers[i]);
        SSTriggerVTablePatchItem newItem = {
            .vtbUid = pUids[i], .ver = pVers[i], .vgId = vgId, .op = TABLE_BLOCK_RETIRE};
        SSHashObj                *pPatchItems = pContext->patchContext.pPatchItems;
        // Same invariant as the TABLE_BLOCK_ADD branch: pPatchItems is initialized for every
        // virtual-table context, enforce it instead of silently skipping the patch queue entry.
        QUERY_CHECK_NULL(pPatchItems, code, lino, _end, TSDB_CODE_STREAM_INTERNAL_ERROR);
        SSTriggerVTablePatchItem *pExist = tSimpleHashGet(pPatchItems, &pUids[i], sizeof(int64_t));
        if (pExist == NULL) {
          code = tSimpleHashPut(pPatchItems, &pUids[i], sizeof(int64_t), &newItem, sizeof(SSTriggerVTablePatchItem));
          QUERY_CHECK_CODE(code, lino, _end);
        } else {
          *pExist = newItem;
        }
        pProgress->savedTbVer = TMAX(pProgress->savedTbVer, pVers[i]);
#else
        ST_TASK_DLOG("found dropped virtual table, uid:%" PRId64, pUids[i]);
        code = TSDB_CODE_INTERNAL_ERROR;
        QUERY_CHECK_CODE(code, lino, _end);
#endif
      } else if (pTypes[i] == TABLE_BLOCK_DROP) {
        ST_TASK_DLOG("found runtime table drop, uid:%" PRId64 ", ver:%" PRId64, pUids[i], pVers[i]);
        int64_t gid = pUids[i];
        void   *pGroup = tSimpleHashGet(pContext->pGroups, &gid, sizeof(int64_t));
        if (pGroup == NULL) {
          pGroup = taosMemoryCalloc(1, sizeof(SSTriggerRealtimeGroup));
          QUERY_CHECK_NULL(pGroup, code, lino, _end, terrno);
          code = tSimpleHashPut(pContext->pGroups, &gid, sizeof(int64_t), &pGroup, POINTER_BYTES);
          if (code != TSDB_CODE_SUCCESS) {
            taosMemoryFreeClear(pGroup);
            QUERY_CHECK_CODE(code, lino, _end);
          }
          code = stRealtimeGroupInit(pGroup, pContext, gid, vgId);
          QUERY_CHECK_CODE(code, lino, _end);
        }

        void *px = taosArrayPush(pContext->groupsToDelete, &pUids[i]);
        QUERY_CHECK_NULL(px, code, lino, _end, terrno);
      }
    }
  }

_end:
  if (code == TSDB_CODE_SUCCESS && (pContext->pPeriod == NULL || pContext->pPeriod->pReceiving == NULL)) {
    // A reader missing from a restored checkpoint starts at zero and reads the retained WAL.
    if (scannedFromZero) pProgress->zeroStartConfirmed = true;
    stTriggerTaskUpdateReaderProgress(pTask, pProgress);
  }
  if (code != TSDB_CODE_SUCCESS) {
    ST_TASK_ELOG("%s failed at line %d since %s", __func__, lino, tstrerror(code));
  }
  return code;
}

