int32_t stTriggerTestProcWalMeta(SSTriggerRealtimeContext *pContext, SSTriggerWalProgress *pProgress,
                                 int64_t nowNs) {
  return stRealtimeContextProcWalMeta(pContext, pProgress, nowNs);
}
